    --tree-row-marker: var(--workspace-selection-bar);
    --mode-auto-bg: #2f5fa8;
    --mode-auto-border: #386dbb;
    --mode-auto-fg: #fff;
    --mode-plan-bg: var(--accent-soft);
    --mode-plan-border: color-mix(in srgb, var(--accent) 32%, var(--border));
    --mode-plan-fg: var(--accent);
    --mode-yolo-bg: #e5484d;
    --mode-yolo-border: #ed5d62;
