.sidebar-resizer::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: -3px;
  right: -3px;
}
.sidebar-resizer::after {
  display: none;
}
.sidebar-resizer:hover,
.sidebar-resizer:focus-visible,
.layout--sidebar-resizing .sidebar-resizer {
  background: var(--accent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 24%, transparent);
}
.layout--sidebar-collapsed .sidebar-resizer {
  display: none;
}
.workspace-panel-resizer {
  --wails-draggable: no-drag;
  position: relative;
  grid-row: 2;
  grid-column: 3;
  align-self: stretch;
  justify-self: start;
  width: 1px;
  min-width: 1px;
  height: 100%;
  padding: 0;
  border: 0;
  background: var(--border-soft);
  cursor: col-resize;
  touch-action: none;
  z-index: var(--z-layout-resizer-active);
}
.workspace-panel-resizer::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  right: -7px;
}
.workspace-panel-resizer::after {
  display: none;
}
.workspace-panel-resizer:hover,
.workspace-panel-resizer:focus-visible,
.layout--workspace-resizing .workspace-panel-resizer {
  background: var(--accent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 24%, transparent);
}
.chat-pane {
  position: relative;
  grid-row: 2;
  grid-column: 2;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  background: var(--chat-bg);
}

/* ── top bar (drag region) ───────────────────────────────────────────────── */
.topbar {
  position: relative;
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 12px;
  height: 50px;
  padding: 0 18px;
  background: var(--chat-bg);
  border-bottom: 1px solid var(--border-soft);
  --wails-draggable: drag;
  user-select: none;
}
.topbar__identity {
  display: flex;
  min-width: 0;
  flex-direction: column;
  justify-content: center;
  line-height: 1.25;
  pointer-events: none;
}
.topbar__title {
  color: var(--fg);
  font-size: 13px;
  font-weight: 600;
}
.topbar__model {
  font-family: inherit;
  font-size: 11px;
  color: var(--fg-dim);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.topbar__spacer {
  flex: 1;
}
.topbar__actions {
  display: none;
  align-items: center;
  gap: 8px;
}
.topbar__workspace-toggle {
  display: inline-flex;
}
.chip {
  --wails-draggable: no-drag;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  height: var(--button-small-height);
  padding: 0 10px;
  border: 1px solid var(--button-border);
  background: var(--button-bg);
  color: var(--button-muted-fg);
  font: inherit;
  font-size: var(--font-control-small);
  font-weight: 500;
  line-height: 1.25;
  border-radius: var(--button-radius);
  transition: color 0.12s, border-color 0.12s, background 0.12s;
}
.chip--icon {
  width: var(--button-icon-size);
  padding: 0;
}
.chip:hover {
  color: var(--fg);
  background: var(--button-bg-hover);
  border-color: var(--button-border-hover);
}
.chip:disabled {
  opacity: 0.4;
  cursor: default;
}
.chip:disabled:hover {
  color: var(--button-muted-fg);
  background: var(--button-bg);
  border-color: var(--button-border);
}
.chip--on {
  color: var(--accent);
  background: var(--accent-soft);
  border-color: transparent;
}

.modal-close-button {
  --wails-draggable: no-drag;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  width: var(--button-icon-size);
  height: var(--button-icon-size);
  padding: 0;
  border: 1px solid transparent;
  border-radius: var(--button-icon-radius, 8px);
  background: transparent;
  color: var(--fg-faint);
  font: inherit;
  line-height: 1;
  transition:
    color var(--dur-fast),
    border-color var(--dur-fast),
    background var(--dur-fast),
    transform var(--dur-fast) var(--ease-out);
}

.modal-close-button:hover {
  color: var(--fg);
  border-color: var(--button-border);
  background: color-mix(in srgb, var(--fg-faint) 8%, transparent);
}

.modal-close-button:active {
  transform: scale(0.94);
  background: color-mix(in srgb, var(--fg-faint) 14%, transparent);
}

.modal-close-button:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--accent) 52%, transparent);
  outline-offset: 2px;
}

.modal-close-button:disabled {
  opacity: 0.4;
}

.banner {
  flex: 0 0 auto;
  padding: 8px 16px;
  font-size: var(--font-control-small);
}
.banner--error {
  background: var(--del-bg);
  color: var(--err);
  border-bottom: 1px solid var(--border-soft);
}
.banner--warning {
  background: color-mix(in srgb, var(--warn) 12%, var(--bg-elev));
  color: var(--warn);
  border-bottom: 1px solid var(--border-soft);
}
.banner--success {
  background: color-mix(in srgb, var(--ok) 10%, var(--bg-elev));
  color: var(--ok);
  border-bottom: 1px solid var(--border-soft);
}
.banner--update {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--accent-soft);
  color: var(--fg);
  border-bottom: 1px solid var(--border-soft);
}
.banner--update.banner--error {
  background: var(--del-bg);
  color: var(--err);
  border-bottom-color: color-mix(in srgb, var(--err) 24%, var(--border-soft));
}
.banner--actionable {
  display: flex;
  align-items: center;
  gap: 10px;
}
.banner__msg {
  min-width: 0;
  font-weight: 500;
}
.banner--actionable .banner__msg {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.banner__hint {
  color: var(--fg-dim);
  font-size: var(--font-caption);
}
.banner__spacer {
  flex: 1 1 auto;
}
.banner--actionable .btn {
  flex: 0 0 auto;
}
.banner__progress {
  width: 180px;
  height: 8px;
  accent-color: var(--accent);
}

/* ── transcript ──────────────────────────────────────────────────────────── */
.main {
  flex: 1 1 auto;
  overflow: hidden;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

/* loading screen shown while boot.Build runs in the background */
.loading-screen {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  opacity: 0;
  animation: anim-fade-in 0.4s ease forwards;
}
.loading-screen__spinner {
  width: 28px;
  height: 28px;
  border: 3px solid var(--border);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}
.loading-screen__text {
  font-size: 13px;
  color: var(--fg-faint);
  letter-spacing: 0.3px;
}
@keyframes anim-fade-in {
  to {
    opacity: 1;
  }
}
.bot-detail {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  display: grid;
  align-content: start;
  gap: 12px;
  width: min(100%, 880px);
  margin: 0 auto;
  padding: 26px clamp(18px, 4vw, 48px);
}
.bot-detail__summary {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px 14px;
  min-width: 0;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg-elev);
  padding: 14px 16px;
}
.bot-detail__avatar {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 42px;
  height: 42px;
  border-radius: 9px;
  color: #fff;
  font-size: 16px;
  font-weight: 800;
}
.bot-detail__avatar--feishu {
  background: #2f80ff;
}
.bot-detail__avatar--qq {
  background: #ff5a3d;
}
.bot-detail__avatar--lark {
  background: #4f7dff;
}
.bot-detail__avatar--weixin {
  background: #22b35f;
}
.bot-detail__summary-main {
  display: grid;
  flex: 1 1 250px;
  gap: 4px;
  min-width: 0;
}
.bot-detail__summary-main > span {
  color: var(--fg-faint);
  font-size: 11px;
  font-weight: 650;
}
.bot-detail__summary-main h2 {
  min-width: 0;
  overflow: hidden;
  margin: 0;
  color: var(--fg);
  font-size: 18px;
  font-weight: 760;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.bot-detail__chips {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
}
.bot-detail__chips span {
  min-height: 20px;
  border: 1px solid var(--border-soft);
  border-radius: 999px;
  background: var(--bg-elev-2);
  color: var(--fg-dim);
  font-size: 11px;
  font-weight: 650;
  padding: 1px 7px;
}
.bot-detail__primary,
.bot-detail__summary-actions .btn {
  display: flex;
  align-items: center;
  gap: 6px;
}
.bot-detail__summary-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex: 1 1 320px;
  flex-wrap: wrap;
  gap: 8px;
  min-width: 0;
}
.bot-detail__panel {
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg-elev);
}
.bot-detail__panel {
  display: grid;
  gap: 12px;
  padding: 13px 14px;
}
.bot-detail__section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-width: 0;
}
.bot-detail__section-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 8px;
  min-width: 0;
}
.bot-detail__section-actions .copybtn {
  min-height: 28px;
}
.bot-detail__section-head span,
.bot-detail__panel span {
  color: var(--fg-faint);
  font-size: 11px;
  font-weight: 750;
}
.bot-detail__section-head strong {
  min-width: 0;
  overflow: hidden;
  color: var(--fg);
  font-size: 13px;
  font-weight: 750;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.bot-detail__facts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 14px;
  border-top: 1px solid var(--border-soft);
  padding-top: 12px;
}
.bot-detail__facts > div {
  display: grid;
  gap: 7px;
  min-width: 0;
}
.bot-detail__facts span {
  color: var(--fg-faint);
  font-size: 11px;
  font-weight: 750;
}
.bot-detail__facts strong,
.bot-detail__facts code {
  min-width: 0;
  overflow: hidden;
  color: var(--fg);
  font-size: 13px;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.bot-detail__facts code {
  display: block;
  width: fit-content;
  max-width: 100%;
  border-radius: 6px;
  background: var(--bg-elev-2);
  color: var(--fg-dim);
  font-family: var(--mono);
  font-size: 12px;
  padding: 4px 6px;
}
.bot-detail__access-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 14px;
  border-top: 1px solid var(--border-soft);
  padding-top: 12px;
}
.bot-detail__access-grid > div,
.bot-detail__allowlist {
  display: grid;
  gap: 7px;
  min-width: 0;
}
.bot-detail__access-grid strong,
.bot-detail__access-grid code,
.bot-detail__id-list code {
  min-width: 0;
  overflow: hidden;
  color: var(--fg);
  font-size: 13px;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.bot-detail__access-grid code,
.bot-detail__id-list code {
  display: block;
  width: fit-content;
  max-width: 100%;
  border-radius: 6px;
  background: var(--bg-elev-2);
  color: var(--fg-dim);
  font-family: var(--mono);
  font-size: 12px;
  padding: 4px 6px;
}
.bot-detail__access-status--ok {
  color: var(--ok) !important;
}
.bot-detail__access-status--warn {
  color: var(--warning, var(--accent)) !important;
}
.bot-detail__access-status--muted {
  color: var(--fg-dim) !important;
}
.bot-detail__id-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  min-width: 0;
}
.bot-detail__id-list code {
  max-width: min(100%, 360px);
}
.bot-detail__id-list .bot-detail__id-list-item--active {
  border: 1px solid color-mix(in srgb, var(--ok) 34%, var(--border-soft));
  background: color-mix(in srgb, var(--ok) 10%, var(--bg-elev-2));
  color: var(--fg);
}
.bot-detail__id-list em {
  color: var(--fg-dim);
  font-size: 13px;
  font-style: normal;
}
.bot-detail__panel strong {
  color: var(--fg);
  font-size: 13px;
  font-weight: 650;
  line-height: 1.5;
}

/* Startup splash restored from the v0.50 desktop intro. It masks cold boot while
/* Startup splash restored from the v0.50 desktop intro. It masks cold boot while
   the Wails bridge and background startup work settle, then yields to the app. */
.startup-splash {
  position: fixed;
  inset: 0;
  z-index: var(--z-startup-overlay);
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  transition: opacity 0.42s ease;
}
.startup-splash[data-leaving="true"] {
  opacity: 0;
  pointer-events: none;
}
.startup-splash__card {
  display: flex;
  flex-direction: column;
  align-items: center;
  animation: startup-splash-in 0.55s cubic-bezier(0.2, 0.7, 0.1, 1) both;
}
.startup-splash__mark {
  width: 64px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: center;
  filter: drop-shadow(0 14px 22px color-mix(in srgb, #0153e5 34%, transparent));
  margin-bottom: 22px;
}
.startup-splash__mark img {
  width: 64px;
  height: 64px;
  display: block;
}
.startup-splash__name {
  font-size: 27px;
  font-weight: 650;
  letter-spacing: 0;
  line-height: 1.1;
  color: var(--fg);
}
.startup-splash__sub {
  margin-top: 9px;
  font-size: 13px;
  letter-spacing: 0.05em;
  color: var(--fg-faint);
}
.startup-splash__dots {
  display: flex;
  gap: 8px;
  margin-top: 31px;
}
.startup-splash__dots span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--fg-faint);
  animation: startup-splash-pulse 1s ease-in-out infinite;
}
.startup-splash__dots span:nth-child(2) {
  animation-delay: 0.16s;
}
.startup-splash__dots span:nth-child(3) {
  animation-delay: 0.32s;
}
@keyframes startup-splash-in {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes startup-splash-pulse {
  0%, 100% {
    opacity: 0.25;
    transform: scale(0.8);
  }
  50% {
    opacity: 1;
    transform: scale(1);
  }
}
.transcript {
  /* Keep horizontal inset on blocks so the native scroller's geometry is
     independent of readable content width. */
  --transcript-inline-pad: 32px;
  position: relative;
  /* TranscriptKernel owns logical anchors and applies at most one structural
     correction per geometry revision. */
  overflow-anchor: none;
  height: 100%;
  overflow-y: auto;
  overflow-y: overlay;
  overflow-x: hidden;
  scrollbar-gutter: stable both-edges;
  padding: 24px 0 32px;
  scrollbar-width: thin;
  scrollbar-color: var(--scrollbar-thumb) var(--scrollbar-track);
}
.transcript-shell {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  height: 100%;
}
.transcript-navigation-surface {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
}
.transcript-navigation-content {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  height: 100%;
}
.transcript-navigation-overlay {
  position: absolute;
  inset: 0;
  z-index: var(--z-inline-sticky);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  color: var(--fg);
  background: var(--chat-bg, var(--bg));
  pointer-events: auto;
  user-select: none;
  cursor: progress;
}
.transcript-navigation-overlay__spinner {
  width: 16px;
  height: 16px;
  border: 2px solid color-mix(in srgb, var(--fg) 24%, transparent);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: transcript-navigation-spin 0.8s linear infinite;
}
@keyframes transcript-navigation-spin {
  to { transform: rotate(360deg); }
}
@media (prefers-reduced-motion: reduce) {
  .transcript-navigation-overlay__spinner { animation: none; }
}
.transcript__live-status {
  display: flex;
  align-items: center;
  gap: 6px;
  box-sizing: border-box;
  width: 100%;
  max-width: var(--maxw);
  margin-left: auto;
  margin-right: auto;
  padding: 4px var(--transcript-inline-pad, 32px) 12px;
  color: var(--fg-dim);
  font-size: var(--text-sm);
}
.transcript > * {
  max-width: var(--maxw);
  margin-left: auto;
  margin-right: auto;
}

/* ── Transcript projection and window adapter ───────────────────── */
.transcript__projection,
.transcript__block,
.transcript__resident-tail {
  position: relative;
}
.transcript > .transcript__projection {
  max-width: none;
  margin-left: 0;
  margin-right: 0;
}
.transcript__block {
  display: flow-root;
}
.transcript__window-item {
  box-sizing: border-box;
  width: 100%;
}
.transcript__row {
  position: relative;
  display: flow-root;
  box-sizing: border-box;
  padding-left: var(--transcript-inline-pad, 32px);
  padding-right: var(--transcript-inline-pad, 32px);
}
.transcript__header {
  display: flow-root;
  box-sizing: border-box;
  width: 100%;
  padding-left: var(--transcript-inline-pad, 32px);
  padding-right: var(--transcript-inline-pad, 32px);
}
.transcript__header > * {
  max-width: var(--maxw);
  margin-left: auto;
  margin-right: auto;
}
.transcript__older-status {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 36px;
  color: var(--fg-faint);
  font-size: 12px;
}
.transcript__older-status .btn {
  flex-shrink: 0;
}
.transcript__older-spinner {
  flex-shrink: 0;
  animation: spin 0.8s linear infinite;
}
.transcript-selection-overlay {
  position: absolute;
  inset: 0;
  z-index: var(--z-local-handle);
  pointer-events: none;
  overflow: visible;
}
.transcript-selection-overlay__rect {
  position: absolute;
  display: block;
  border-radius: 2px;
  background: color-mix(in srgb, Highlight 34%, transparent);
}
.transcript__row > * {
  max-width: var(--maxw);
  margin-left: auto;
  margin-right: auto;
}
.transcript__row > *:first-child {
  margin-top: 0;
}
.history-preview__body .transcript__row > * {
  max-width: none;
}
/* Keep the lazy Markdown source readable while the parser resolves the real
   parser result. The row itself remains free to measure once the marker is
   removed; no manual-scroll path writes a forced row height. */
.transcript__row .msg--assistant .msg__body > .md[data-transcript-geometry-pending] {
  box-sizing: border-box;
  height: max(0px, calc(var(--transcript-row-estimate) - 32px));
  overflow: hidden;
}
/* Offscreen blocks are unmounted by the window adapter, so content-visibility
   culling is redundant inside rows — and skipping it keeps offsetHeight
   measurements exact instead of contain-intrinsic-size placeholders. */
.transcript__row .msg,
.transcript__row .turn-collapse,
.transcript__row .tool,
.transcript__row .process-card,
.transcript__row .readonly-batch,
.transcript__row .tool-group,
.transcript__row .md > * {
  content-visibility: visible;
  contain-intrinsic-size: none;
}
.transcript__jump-bottom:not([hidden]) {
  --wails-draggable: no-drag;
  position: absolute;
  left: 50%;
  bottom: 34px;
  z-index: var(--z-inline-sticky);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  padding: 0;
  border: 1px solid color-mix(in srgb, var(--accent) 22%, var(--border));
  border-radius: 999px;
  background: color-mix(in srgb, var(--bg-elev) 92%, var(--accent-soft));
  color: var(--fg);
  box-shadow: var(--shadow-2);
  cursor: pointer;
  pointer-events: auto;
  transform: translateX(-50%);
  transition:
    transform 0.12s ease,
    background 0.12s ease,
    border-color 0.12s ease,
    color 0.12s ease,
    box-shadow 0.12s ease,
    opacity 0.12s ease;
}
.transcript__jump-bottom:hover {
  transform: translate(-50%, -1px);
  border-color: color-mix(in srgb, var(--accent) 40%, var(--border));
  background: color-mix(in srgb, var(--bg-elev-2) 88%, var(--accent-soft));
  color: var(--accent);
  box-shadow: 0 12px 30px color-mix(in srgb, var(--accent) 18%, transparent);
}
.transcript__jump-bottom:focus-visible {
  outline: none;
  box-shadow:
    var(--focus-ring),
    var(--shadow-2);
}
.transcript--empty {
  container-type: size;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  overflow-x: hidden;
  overflow-y: auto;
  padding: 16px 32px;
}
.transcript--empty > * {
  max-width: none;
}
.transcript--empty > .welcome {
  margin-block: auto;
  margin-inline: 0;
}
.transcript__loading {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin: auto;
  color: var(--fg-faint);
  font-size: 13px;
}
.transcript__loading-icon {
  width: 16px;
  height: 16px;
  animation: navigation-surface-spin 0.8s linear infinite;
}
@keyframes navigation-surface-spin {
  to { transform: rotate(360deg); }
}
.warm-collapse {
  display: block;
  width: 100%;
  max-width: var(--maxw);
  margin: 6px auto;
  padding: 11px 14px;
  border: 1px dashed var(--border);
  border-radius: 8px;
  background: transparent;
  color: var(--fg-faint);
  font: inherit;
  font-size: 12.5px;
  text-align: center;
  cursor: pointer;
  transition: color 0.12s, border-color 0.12s, background 0.12s;
}
.warm-collapse:hover {
  color: var(--fg);
  border-color: var(--accent-soft);
  background: var(--bg-elev);
}
.warm-collapse:disabled {
  cursor: wait;
  opacity: 0.65;
}

/* ── Notice line (replaces full ProcessCard for notices) ─────────── */
.notice-line {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 6px 8px;
  font-size: 13px;
  line-height: 1.5;
  color: var(--fg-faint);
  border-radius: 6px;
}
.notice-line--warn {
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 8%, transparent);
}
.notice-line--completion,
.notice-line--delivery {
  gap: 9px;
  padding: 10px 12px;
  color: var(--fg-dim);
  background: color-mix(in srgb, var(--bg-soft) 76%, var(--bg-elev));
  border: 1px solid var(--border-soft);
}
.notice-line--delivery .notice-line__icon {
  color: var(--fg-faint);
  margin-top: 2px;
}
.notice-line__icon {
  flex: 0 0 auto;
}
.notice-line__text {
  flex: 1;
  min-width: 0;
  word-break: break-word;
}
.notice-line__title {
  color: var(--fg);
  font-weight: 600;
}
.notice-line__body {
  min-width: 0;
}
.notice-line__decision-receipt {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 6px 9px;
  min-width: 0;
  line-height: 1.4;
}
.notice-line__decision-title {
  color: var(--fg);
  font-weight: 650;
}
.notice-line__decision-outcome {
  color: var(--accent);
  font-weight: 600;
}
.notice-line__decision-receipt code {
  color: var(--fg-dim);
  font-family: var(--mono);
  font-size: 11px;
}
.notice-line__decision-subject {
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--fg-dim);
}

/* ── Extension card (extension-published structured surface) ───────── */
.extension-card {
  display: grid;
  gap: 8px;
  padding: 10px 12px;
  font-size: 13px;
  line-height: 1.5;
  color: var(--fg-dim);
  background: color-mix(in srgb, var(--bg-soft) 76%, var(--bg-elev));
  border: 1px solid var(--border-soft);
  border-radius: 8px;
}
.extension-card__header {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}
.extension-card__icon {
  flex: 0 0 auto;
  color: var(--fg-faint);
}
.extension-card__title {
  color: var(--fg);
  font-weight: 600;
  word-break: break-word;
}
.extension-card__plugin {
  margin-left: auto;
  flex: 0 0 auto;
  font-size: 11px;
  color: var(--fg-faint);
  border: 1px solid var(--border-soft);
  border-radius: 999px;
  padding: 0 8px;
}
.extension-card__body {
  min-width: 0;
  word-break: break-word;
}
.extension-card__fields {
  display: grid;
  gap: 4px;
  margin: 0;
}
.extension-card__field {
  display: flex;
  gap: 8px;
  min-width: 0;
}
.extension-card__field dt {
  flex: 0 0 auto;
  color: var(--fg-faint);
}
.extension-card__field dd {
  margin: 0;
  min-width: 0;
  word-break: break-word;
  color: var(--fg);
}
.extension-card__progress {
  height: 4px;
  border-radius: 999px;
  overflow: hidden;
  background: color-mix(in srgb, var(--fg-faint) 18%, transparent);
}
.extension-card__progress-fill {
  height: 100%;
  border-radius: inherit;
  background: var(--accent);
}
.extension-card__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.extension-card__result {
  font-size: 12px;
  color: var(--fg-dim);
}
.extension-card__result--error {
  color: var(--danger);
}
.notice-line__title + .notice-line__body {
  margin-top: 2px;
}
.notice-line__actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
}
.notice-line__details {
  margin-top: 4px;
  color: var(--fg-faint);
  font-size: 12px;
  line-height: 1.45;
}
.notice-line__details summary {
  cursor: pointer;
  user-select: none;
}
.notice-line__details div {
  margin-top: 4px;
  white-space: pre-wrap;
}

/* ── Steer line (mid-turn user guidance, rendered on the user side) ── */
.steer-line {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}
.steer-line__bubble {
  display: inline-flex;
  align-items: flex-start;
  gap: 6px;
  max-width: 82%;
  padding: 6px 12px;
  border: 1px solid var(--chat-user-border);
  border-radius: 12px;
  background: color-mix(in srgb, var(--chat-user-bg) 55%, transparent);
  color: var(--chat-user-fg);
  font-size: 13px;
  line-height: 1.5;
}
.steer-line__icon {
  flex: 0 0 auto;
  color: var(--fg-faint);
}
.steer-line__text {
  min-width: 0;
  word-break: break-word;
  white-space: pre-wrap;
}

/* ── ReadOnly batch (parent fold for read/search tools) ────────────── */
.readonly-batch {
  margin: 2px auto;
}

/* Expanded padding — the parent --open class drives it while native motion handles height. */
.readonly-batch--open .readonly-batch__body,
.turn-collapse--open .turn-collapse__body,
.tool--open .tool__body {
  padding: 0 11px 10px 12px;
  margin-top: 6px;
}

/* shared body border-left for fold containers */
.readonly-batch__body,
.turn-collapse__body {
  overflow: hidden;
  padding-left: 12px;
  border-left: 2px solid var(--border);
}
.readonly-batch__body > *,
.turn-collapse__body > * {
  max-width: var(--maxw-inner);
  margin-left: auto;
  margin-right: auto;
  margin-bottom: 6px;
}

/* ── TurnCollapse: fold line for completed steps ──────────────────── */
.turn-collapse {
  margin: 4px auto;
  content-visibility: auto;
  contain-intrinsic-size: 1px 36px;
}
.turn-collapse__label {
  white-space: nowrap;
}

.transcript-shell > .jump-bar {
  position: absolute;
  top: 50%;
  right: 0;
  z-index: var(--z-inline-sticky);
  max-width: none;
  margin: 0;
  transform: translate(4px, -50%);
}
.jump-bar {
  z-index: var(--z-inline-sticky);
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  width: 56px;
  height: 240px;
  padding: 0 12px;
  opacity: 0;
  pointer-events: none;
  animation: jump-bar-in 0.18s ease-out 0.08s forwards;
}
.jump-scroll {
  position: relative;
  width: 32px;
  height: 100%;
  cursor: pointer;
  pointer-events: auto;
  outline: none;
}
.jump-item {
  position: absolute;
  left: 0;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  width: 32px;
  height: 3px;
  transform: translateY(-50%);
  pointer-events: none;
}
.jump-scroll:focus-visible {
  border-radius: 4px;
  box-shadow: 0 0 0 3px var(--accent-soft);
}
.jump-dot {
  pointer-events: none;
  height: 3px;
  border-radius: 2px;
  background: var(--border);
  transition:
    background 200ms,
    width 400ms cubic-bezier(0.34, 1.56, 0.64, 1),
    box-shadow 150ms;
}
.jump-scroll[data-density="compact"] .jump-dot {
  height: 2px;
}
.jump-scroll[data-density="packed"] .jump-dot {
  height: 1px;
}
.jump-item[data-loaded="false"] .jump-dot {
  background: color-mix(in srgb, var(--border) 55%, transparent);
}
.jump-dot[data-d="0"] {
  background: var(--accent);
}
.jump-dot[data-d="1"] {
  background: color-mix(in srgb, var(--accent) 60%, transparent);
}
.jump-dot[data-d="2"] {
  background: color-mix(in srgb, var(--accent) 35%, transparent);
}
.jump-preview {
  position: absolute;
  right: 100%;
  top: 0;
  max-width: 240px;
  margin-right: 12px;
  padding: 4px 8px;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg-elev);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.18);
  color: var(--fg);
  font-size: 12px;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
  pointer-events: none;
  transform: translateY(-50%);
}
.jump-text {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
}
@keyframes jump-bar-in {
  to {
    opacity: 1;
    transform: translate(0, -50%);
  }
}

.welcome {
  --welcome-brand-width: 240px;
  --welcome-brand-height: 56px;
  --welcome-brand-gap: 26px;
  width: min(100%, 600px);
  max-height: none;
  min-height: 0;
  display: grid;
  align-content: center;
  justify-items: center;
  gap: 0;
  align-items: center;
  text-align: center;
  color: var(--fg-faint);
  overflow: visible;
}
/* Welcome container breathing room (classic + workbench only) */
.app:not(.app--creation) .welcome {
  padding: 24px 28px;
  border-radius: 14px;
}
.welcome--brand {
  margin-top: 0;
  transform: translateY(-20px);
}
.welcome__brand {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--welcome-brand-gap);
}
.welcome__brand-logo {
  display: block;
  width: var(--welcome-brand-width);
  height: var(--welcome-brand-height);
  object-fit: contain;
}

:root[data-theme="dark"] .sidebar__brand-logo,
:root[data-theme="dark"] .welcome__brand-logo {
  filter: brightness(0) invert(1);
  opacity: 0.94;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) .sidebar__brand-logo,
  :root:not([data-theme]) .welcome__brand-logo {
    filter: brightness(0) invert(1);
    opacity: 0.94;
  }
}
.welcome__title {
  font-size: 22px;
  font-weight: 650;
  color: var(--fg);
  letter-spacing: 0.3px;
}
.welcome__tag {
  margin-top: 6px;
  font-size: 13.5px;
  color: var(--fg-dim);
}
.welcome__hints {
  display: flex;
  gap: 16px;
  margin-top: 18px;
  font-size: 12.5px;
}
.welcome__hints span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.welcome kbd {
  font-family: var(--mono);
  font-size: 11px;
  color: var(--fg-dim);
  background: var(--bg-elev-2);
  border: 1px solid var(--border);
  border-radius: 5px;
  padding: 1px 6px;
  min-width: 18px;
  text-align: center;
}
.welcome__examples {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
  margin-top: 26px;
  width: 100%;
  max-width: 460px;
}
.welcome__ex {
  text-align: left;
  background: var(--bg-soft);
  border: 1px solid var(--border-soft);
  color: var(--fg-dim);
  font: inherit;
  font-size: 13px;
  padding: 9px 13px;
  border-radius: 9px;
  transition: color 0.12s, border-color 0.12s, background 0.12s;
}
.welcome__ex:hover {
  color: var(--fg);
  border-color: var(--accent-soft);
  background: var(--bg-elev);
}

@container (max-height: 560px) {
  .welcome--brand {
    --welcome-brand-width: 224px;
    --welcome-brand-height: 52px;
    --welcome-brand-gap: 22px;
    transform: translateY(-16px);
  }
  .welcome__brand {
    margin-bottom: var(--welcome-brand-gap);
  }
  .welcome__title {
    font-size: 20px;
  }
  .welcome__tag {
    margin-top: 4px;
    font-size: 13px;
  }
  .welcome__hints {
    margin-top: 12px;
  }
  .welcome__examples {
    gap: 7px;
    margin-top: 18px;
  }
  .welcome__ex {
    padding: 8px 12px;
  }
}

@container (max-height: 430px) {
  .welcome__brand {
    display: none;
  }
  .welcome__title {
    font-size: 19px;
  }
  .welcome__tag {
    font-size: 12.5px;
  }
  .welcome__hints {
    gap: 10px;
    margin-top: 10px;
  }
  .welcome__examples {
    gap: 6px;
    margin-top: 14px;
  }
  .welcome__ex {
    padding: 7px 11px;
  }
}

@container (max-height: 330px) {
  .transcript--empty > .welcome {
    margin-block: 0 auto;
  }
  .welcome--brand {
    transform: none;
  }
  .welcome__tag,
  .welcome__hints {
    display: none;
  }
  .welcome__examples {
    margin-top: 12px;
  }
}

/* ── messages ────────────────────────────────────────────────────────────── */
.msg {
  --wails-draggable: no-drag;
  margin: 18px auto;
  user-select: text;
  -webkit-user-select: text;
  content-visibility: auto;
  contain-intrinsic-size: 1px 60px;
}
/* The transcript window adapter already bounds mounted blocks. A second
 * content-visibility viewport would replace real measurements with an
 * intrinsic placeholder, so keep it only for non-transcript message lists. */
.transcript__row .msg {
  content-visibility: visible;
  contain-intrinsic-size: auto;
}
.msg--user {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  color: var(--fg);
}
.msg--user .msg__body {
  max-width: 82%;
  background: var(--chat-user-bg);
  border: 1px solid var(--chat-user-border);
  border-radius: 14px;
  color: var(--chat-user-fg);
  padding: 10px 16px;
  position: relative;
  box-shadow: var(--chat-user-shadow);
}
.msg--user .msg__body--editing {
  width: min(82%, 680px);
  min-width: min(420px, 82%);
  padding: 14px 16px 16px;
  border-radius: 18px;
}
.msg-edit {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.msg-edit__attachments {
  margin-bottom: 0;
}
.msg-edit__input {
  width: 100%;
  min-height: 78px;
  padding: 0;
  border: none;
  outline: none;
  resize: vertical;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: var(--text-lg);
  font-weight: 450;
  line-height: 1.65;
  white-space: pre-wrap;
}
.msg-edit__input:disabled {
  opacity: 0.72;
}
.msg-edit__actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}
.msg-edit__btn {
  min-height: 34px;
  padding: 0 14px;
  border: 1px solid var(--button-border);
  border-radius: var(--button-radius);
  background: var(--button-bg);
  color: var(--button-fg);
  font: inherit;
  font-size: var(--text-md);
  font-weight: 650;
  line-height: 1;
  transition: color 0.12s, background 0.12s, border-color 0.12s, opacity 0.12s;
}
.msg-edit__btn:hover:not(:disabled),
.msg-edit__btn:focus-visible:not(:disabled) {
  background: var(--button-bg-hover);
  border-color: var(--button-border-hover);
}
.msg-edit__btn--primary {
  border-color: var(--control-primary-bg);
  background: var(--control-primary-bg);
  color: var(--control-primary-fg);
}
.msg-edit__btn--primary:hover:not(:disabled),
.msg-edit__btn--primary:focus-visible:not(:disabled) {
  border-color: var(--accent-strong);
  background: var(--accent-strong);
}
.msg-edit__btn:disabled {
  cursor: not-allowed;
  opacity: 0.52;
}
.msg-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 24px;
  margin-top: 4px;
  margin-right: 10px;
  color: var(--fg-faint);
  font-size: var(--font-status);
  line-height: 1;
  user-select: none;
  -webkit-user-select: none;
}
.msg-meta__time {
  color: var(--fg-faint);
  font-variant-numeric: tabular-nums;
}
.msg-meta__indicator {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  color: var(--fg-faint);
  opacity: 0.45;
  cursor: default;
  user-select: none;
  flex-shrink: 0;
}
.msg-meta__btn,
.msg-meta .copybtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  gap: 0;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--fg-faint);
  box-shadow: none;
  transition: color 0.12s, background 0.12s;
}
.msg-meta__btn:hover:not(:disabled),
.msg-meta__btn:focus-visible:not(:disabled),
.msg-meta .copybtn:hover,
.msg-meta .copybtn:focus-visible {
  color: var(--fg);
  background: var(--button-bg-hover);
}
.msg-meta__btn:disabled {
  cursor: not-allowed;
  opacity: 0.4;
}
.rewind {
  position: absolute;
  bottom: -8px;
  right: -8px;
  opacity: 0;
  transition: opacity 120ms ease;
}
.msg--user .msg__body:hover .rewind,
.rewind--open {
  opacity: 1;
}
.rewind__btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 6px;
  color: var(--fg-dim);
  padding: 0;
  box-shadow: 0 1px 4px rgba(0,0,0,0.12);
  transition: background 120ms ease, border-color 120ms ease;
}
.rewind__btn:hover,
.rewind__btn:focus-visible,
.rewind--open .rewind__btn {
  opacity: 1;
  color: var(--accent);
  background: var(--button-bg-hover);
  border-color: var(--button-border-hover);
}
.rewind__menu {
  position: absolute;
  bottom: 100%;
  right: 0;
  margin-bottom: 4px;
  z-index: var(--z-inline-sticky);
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 228px;
  padding: 6px;
  background: var(--bg-soft);
  border: 1px solid var(--border);
  border-radius: 8px;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.28);
}
.rewind__menu-hint {
  padding: 5px 9px;
  color: var(--fg-dim);
  font-size: 11px;
}
.rewind__menu-hint {
  color: var(--warn);
}
.rewind__menu-separator {
  height: 1px;
  margin: 4px 2px;
  background: var(--border);
}
.rewind__menu button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  text-align: left;
  white-space: nowrap;
  background: none;
  border: none;
  color: var(--fg-dim);
  border-radius: 6px;
  font-size: 12px;
  padding: 5px 9px;
}
.rewind__menu-meta {
  color: var(--fg-faint);
  font-size: 11px;
}
.rewind__menu button:hover:not(:disabled),
.rewind__menu button:focus-visible:not(:disabled) {
  background: var(--accent-soft);
  color: var(--fg);
}
.rewind__menu button:hover:not(:disabled) .rewind__menu-meta,
.rewind__menu button:focus-visible:not(:disabled) .rewind__menu-meta {
  color: var(--fg-dim);
}
.rewind__menu button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}
.rewind__menu button.rewind__menu-confirm {
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 10%, transparent);
}
.rewind__menu button.rewind__menu-danger,
.rewind__menu button.rewind__menu-danger.rewind__menu-confirm {
  color: var(--danger);
  background: color-mix(in srgb, var(--danger) 12%, transparent);
}
.msg--user .msg__text {
  white-space: pre-wrap;
  word-break: break-word;
  font-weight: 450;
  line-height: 1.65;
}
.msg--im-source .msg__body {
  min-width: min(520px, 82%);
  max-width: min(760px, 82%);
  padding: 14px 16px;
  background: var(--bg-elev);
  border-color: var(--border);
}
.im-source-card {
  display: flex;
  flex-direction: column;
  gap: 9px;
  min-width: 0;
}
.im-source-card__head {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--fg-dim);
  font-size: 13px;
  font-weight: 650;
}
.im-source-card__head svg {
  color: var(--fg-faint);
}
.im-source-card__text {
  color: var(--fg);
  font-size: 15px;
