  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: center;
  width: 100%;
  height: var(--composer-control-height);
  padding: 2px;
  border: 1px solid var(--border);
