  --composer-modebar-active-fg: var(--mode-auto-fg);
}

/* Two segments instead of three, so the thumb spans half the track. Standard
/* Two segments instead of three, so the thumb spans half the track. Standard
   needs a solid neutral thumb, not the near-invisible default: otherwise
   leaving delivery reads as the pill vanishing rather than sliding. */
.composer-modebar--floor {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  --composer-modebar-active-bg: color-mix(in srgb, var(--fg) 16%, var(--surface-2));
  --composer-modebar-active-border: color-mix(in srgb, var(--fg) 30%, transparent);
  --composer-modebar-active-fg: var(--fg);
}

