  width: calc((100% - 4px) / 2);
}

.composer-modebar--floor[data-floor="delivery"] {
  --composer-modebar-index: 1;
  --composer-modebar-active-bg: var(--accent);
  --composer-modebar-active-border: var(--accent-strong);
  --composer-modebar-active-fg: var(--accent-fg);
}

.composer-modebar--approval[data-mode="auto"] {
  --composer-modebar-active-bg: color-mix(in srgb, var(--ok) 58%, #0b3d24);
  --composer-modebar-active-border: color-mix(in srgb, var(--ok) 76%, #0b3d24);
  --composer-modebar-active-fg: #fff;
}

.composer-modebar--approval[data-mode="yolo"] {
  --composer-modebar-active-bg: var(--mode-yolo-bg);
  --composer-modebar-active-border: var(--mode-yolo-border);
  --composer-modebar-active-fg: var(--mode-yolo-fg);
