.anchored-popover {
  --wails-draggable: no-drag;
  position: fixed;
  z-index: var(--z-popover);
}

.anchored-popover[data-ready="true"][data-state="open"] {
  animation: popover-in var(--dur-base) var(--ease-out) both;
}

.anchored-popover[data-state="closing"] {
  pointer-events: none;
  animation: popover-out var(--dur-fast) var(--ease-out) both;
}

@keyframes popover-in {
  from {
    opacity: 0;
    transform: translateY(calc(-1 * var(--motion-rise))) scale(0.985);
  }
}

@keyframes popover-out {
  to {
    opacity: 0;
    transform: translateY(var(--motion-rise)) scale(0.985);
  }
}

