.statusbar {
  grid-row: 3;
  grid-column: 1 / -1;
  max-width: var(--maxw);
  margin: 7px auto 0;
  display: flex;
  align-items: center;
  gap: 0;
  font-family: var(--font-metadata-family);
  font-size: var(--font-status);
  font-variant-numeric: tabular-nums;
  line-height: 1.35;
  color: var(--fg-faint);
  /* One line, always: without this a narrow window squeezes the flex items and
     CJK text breaks one character per line. The metric chips keep their width
     (flex-shrink: 0) and only the model label ellipsizes to absorb the squeeze.
     Horizontal overflow is scrollable via mouse wheel (scrollbar hidden). */
  white-space: nowrap;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
}
.statusbar::-webkit-scrollbar {
  display: none;
}
.statusbar > * {
  flex-shrink: 0;
}
.statusbar__group {
  display: inline-flex;
  align-items: center;
  gap: 0;
  min-width: 0;
  flex-shrink: 0;
}
.statusbar__group + .statusbar__group {
  margin-left: 18px;
  padding-left: 18px;
  border-left: 1px solid color-mix(in srgb, var(--fg-faint) 18%, transparent);
}
.statusbar__group > * + * {
  display: inline-flex;
  align-items: center;
}
.statusbar__group > * + *::before {
  content: "|";
  margin: 0 9px;
  color: color-mix(in srgb, var(--fg-faint) 50%, transparent);
  font-family: var(--font-mono);
  font-weight: 400;
}
/* shorter separator for intra-item splits like "hit X | miss Y" */
.statusbar__cache-sep {
  margin: 0 4px;
  color: color-mix(in srgb, var(--fg-faint) 50%, transparent);
  font-family: var(--font-mono);
  font-weight: 400;
  font-size: 0.75em;
  line-height: 1;
}
.statusbar__group .tooltip-trigger {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
}
.statusbar__jobs {
  display: inline-flex;
  align-items: center;
}
.statusbar__jobs-trigger {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 1px 4px;
  border: 0;
  border-radius: 4px;
  color: var(--accent-strong);
  background: transparent;
  font: inherit;
  cursor: pointer;
}
.statusbar__jobs-trigger:hover,
.statusbar__jobs-trigger:focus-visible,
.statusbar__jobs-trigger[aria-expanded="true"] {
  background: color-mix(in srgb, var(--accent) 12%, transparent);
}
.statusbar__extension {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--fg-faint);
}
.statusbar__extension--warn {
  color: var(--warn);
}
.statusbar__extension--error {
  color: var(--danger);
}
.statusbar__extension-label {
  max-width: 180px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.jobs-popover {
  width: min(360px, calc(100vw - 16px));
  padding: 8px;
  border: 1px solid var(--border);
  border-radius: 10px;
  box-shadow: var(--shadow-2);
  color: var(--fg);
}
.jobs-popover__header {
  padding: 3px 5px 8px;
  color: var(--fg-dim);
  font-weight: 650;
}
.jobs-popover__list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.jobs-popover__runtime {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.jobs-popover__runtime + .jobs-popover__runtime {
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px solid var(--border);
}
.jobs-popover__runtime-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 2px 4px;
}
.jobs-popover__runtime-header strong {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.jobs-popover__job {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 7px;
  border-radius: 7px;
  background: color-mix(in srgb, var(--bg-elev) 72%, transparent);
}
.jobs-popover__copy {
  display: flex;
  flex: 1 1 auto;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}
.jobs-popover__copy strong,
.jobs-popover__copy small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.jobs-popover__copy small {
  color: var(--fg-faint);
}
.jobs-popover__stop {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: 0 0 auto;
}
.statusbar__item,
.statusbar__item .tooltip-trigger {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
}
.statusbar .modelsw {
  flex-shrink: 1;
  min-width: 0;
}
/* design-spec stat: a "label + bold value" pair separated by the bar's gap. */
.stat {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
.stat b {
  color: var(--fg-dim);
  font-weight: 600;
}
.stat__label {
  color: var(--fg-faint);
}
.stat__label--text {
  flex: 0 0 auto;
  font-weight: 500;
}
.stat__label--icon {
  display: inline-flex;
  width: 13px;
  height: 13px;
  align-items: center;
  justify-content: center;
  flex: 0 0 13px;
}
.stat__label--icon svg {
  display: block;
  stroke-width: 2.15;
}
.statusbar .stat b.stat__value--empty {
  color: var(--fg-faint);
  font-weight: 500;
}
.statusbar__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--ok);
  flex-shrink: 0;
}
.statusbar__dot--busy {
  background: var(--accent);
  animation: pulse 1.2s ease-in-out infinite;
}
@keyframes pulse {
  50% {
    opacity: 0.35;
  }
}
.stat--model {
  flex: 0 1 132px;
  max-width: 132px;
  min-width: 0;
}
.statusbar__model {
  display: block;
  color: var(--fg-dim);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
  font-family: inherit;
}
.statusbar__tooltip-stack {
  display: inline-flex;
  flex-direction: column;
  gap: 2px;
  text-align: left;
}
.statusbar__workspace,
.statusbar__branch {
  max-width: 170px;
}
.statusbar__workspace b,
.statusbar__branch b {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}
.statusbar__workspace b {
  color: var(--fg-dim);
}
.statusbar__branch b {
  color: var(--accent-strong);
}
.statusbar__cache b {
  color: var(--accent-strong);
}
.statusbar .statusbar__cache b.stat__value--empty {
