}
.statusbar .statusbar__rate-value--good {
  color: var(--ok);
  font-weight: 700;
}
.statusbar .statusbar__rate-value--notice {
  color: var(--warn);
  font-weight: 700;
}
.statusbar .statusbar__rate-value--critical {
  color: var(--danger);
  font-weight: 700;
}
.statusbar__cost b,
.statusbar__balance b {
  color: var(--ok);
}
.statusbar__compact b.statusbar__compact-value--warn {
  color: var(--warn);
}
.statusbar__compact b.statusbar__compact-value--critical {
  color: var(--danger);
}
.statusbar__cost {
  justify-content: flex-start;
}
.statusbar__balance {
  justify-content: flex-start;
}
/* model switcher (bottom-of-window popover) */
.modelsw {
  position: relative;
  display: inline-flex;
}
.modelsw__trigger {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: none;
  border: none;
  color: var(--fg-dim);
  font: inherit;
  font-family: inherit;
  font-size: inherit;
  padding: 0;
  white-space: nowrap;
  min-width: 0; /* let the label ellipsize when the status bar is tight */
}
.modelsw__trigger svg {
  flex-shrink: 0;
}
.modelsw__kind {
  color: var(--fg-faint);
  stroke-width: 1.8;
}
.modelsw__trigger:hover .modelsw__kind,
.modelsw__trigger:focus-visible .modelsw__kind {
  color: currentColor;
}
.modelsw__label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}
.modelsw__trigger:hover {
  color: var(--fg);
}
.statusbar .modelsw__trigger {
  font-size: inherit;
}
.modelsw__menu {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 0;
  z-index: var(--z-local-popover);
  min-width: 200px;
  max-height: 50vh;
  overflow-y: auto;
  border: 1px solid var(--border);
  border-radius: 9px;
  padding: 5px;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.45);
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
}
.modelsw__menu::-webkit-scrollbar {
  width: 6px;
}
.modelsw__menu::-webkit-scrollbar-track {
  background: transparent;
  border-radius: 3px;
}
.modelsw__menu::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: 3px;
}
.modelsw__menu::-webkit-scrollbar-thumb:hover {
  background: var(--fg-faint);
}
.modelsw__menu--portal {
  position: fixed;
  left: auto;
  top: auto;
  bottom: auto;
  z-index: var(--z-popover);
  max-height: min(calc(100vh - 16px), 50vh);
  overflow-y: auto;
}
.modelsw__search {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 4px;
  padding: 4px 7px;
  border: 1px solid var(--border);
  border-radius: 6px;
  color: var(--fg-faint);
}
.modelsw__search:focus-within {
  border-color: var(--accent);
}
.modelsw__search-input {
  flex: 1;
  min-width: 0;
  background: none;
  border: none;
  outline: none;
  color: var(--fg);
  font: inherit;
  font-size: 12px;
}
.modelsw__search-input::placeholder {
  color: var(--fg-faint);
}
.modelsw__item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 6px 9px;
  background: none;
  border: none;
  border-radius: 6px;
  color: var(--fg-dim);
  font: inherit;
  font-family: inherit;
  font-size: 12px;
  text-align: left;
}
.modelsw__item:hover {
  background: var(--bg-elev-2);
  color: var(--fg);
}
.modelsw__item--current {
  color: var(--accent);
}
.modelsw__group .modelsw__item {
  padding-left: 26px;
}
.modelsw__copy {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.modelsw__model {
  display: block;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.modelsw__check {
  flex-shrink: 0;
}
.modelsw__empty {
  padding: 6px 9px;
  color: var(--fg-faint);
  font-size: 11.5px;
}
.modelsw__group-label {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 9px 3px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--accent);
}

/* effort switcher: same status-bar affordance as the model switcher */
.effortsw__trigger {
  --wails-draggable: no-drag;
  width: 100%;
}
.effortsw__trigger:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}
.effortsw__trigger--explicit {
  color: var(--accent);
}
.effortsw__menu {
  min-width: 112px;
  max-width: 160px;
}

/* ── approval modal ──────────────────────────────────────────────────────── */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}
.modal {
  width: 100%;
  max-width: 440px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 18px;
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.45);
}
.modal__title {
  font-weight: 600;
  margin-bottom: 12px;
}
.modal__tool {
  margin-bottom: 8px;
}
.modal__subject {
  margin: 0 0 14px;
  padding: 9px 11px;
  background: var(--bg-soft);
  border: 1px solid var(--border-soft);
  border-radius: 7px;
  font-family: var(--mono);
  font-size: 12.5px;
  white-space: pre-wrap;
  max-height: 160px;
  overflow: auto;
}
.modal__actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
  flex-wrap: wrap;
}
.reasonix-confirm-backdrop {
  --wails-draggable: no-drag;
  z-index: var(--z-overlay-backdrop);
}
.reasonix-confirm-dialog {
  max-width: 420px;
  color: var(--fg);
}
.reasonix-confirm-dialog__title { margin-bottom: 8px; }
.reasonix-confirm-dialog__message {
  margin-bottom: 18px;
  color: var(--fg-dim);
  font-size: var(--font-control);
  line-height: 1.55;
  white-space: pre-wrap;
}
.reasonix-confirm-dialog__actions .btn { min-width: 84px; }
.reasonix-confirm-dialog__actions .btn--danger { font-weight: 600; }
.blank-project-backdrop {
  --wails-draggable: no-drag;
  z-index: var(--z-overlay-backdrop);
}
.blank-project-dialog {
  max-width: 460px;
  color: var(--fg);
}
.blank-project-dialog__field {
  display: grid;
  gap: 6px;
  margin-bottom: 14px;
}
.blank-project-dialog__label {
  color: var(--fg-dim);
  font-size: var(--font-caption);
  font-weight: 600;
}
.blank-project-dialog__path {
  display: block;
  overflow: hidden;
  padding: 8px 9px;
  border: 1px solid var(--border-soft);
  border-radius: 7px;
  background: var(--bg-soft);
  color: var(--fg);
  font-family: var(--mono);
  font-size: var(--font-caption);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.blank-project-dialog__input {
  width: 100%;
}
.blank-project-dialog__created,
.blank-project-dialog__error {
  margin: 0 0 12px;
  font-size: var(--font-caption);
  line-height: 1.45;
  overflow-wrap: anywhere;
}
.blank-project-dialog__created {
  color: var(--fg-dim);
}
.blank-project-dialog__error {
  min-height: 1.45em;
  color: var(--err);
}
.blank-project-dialog__actions .btn {
  min-width: 92px;
}
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: var(--button-height);
  padding: 0 var(--button-px);
  border: 1px solid var(--button-border);
  background: var(--button-bg);
  color: var(--button-fg);
  font: inherit;
  font-size: var(--font-control);
  font-weight: 500;
  line-height: 1.25;
  border-radius: var(--button-radius);
  white-space: nowrap;
  transition: color 0.12s, border-color 0.12s, background 0.12s, box-shadow 0.12s;
}
.btn:hover {
  background: var(--button-bg-hover);
  border-color: var(--button-border-hover);
}
.btn:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}
.btn:disabled {
  cursor: default;
  opacity: 0.52;
}
.btn:disabled:hover {
  background: var(--button-bg);
  border-color: var(--button-border);
}
.btn--primary {
  background: var(--control-primary-bg);
  border-color: var(--control-primary-bg);
  color: var(--control-primary-fg);
  font-weight: 600;
}
.btn--primary:hover {
  background: color-mix(in srgb, var(--control-primary-bg) 88%, var(--fg));
  border-color: color-mix(in srgb, var(--control-primary-bg) 88%, var(--fg));
}
.btn--primary:disabled:hover {
  background: var(--control-primary-bg);
  border-color: var(--control-primary-bg);
}
.btn--danger {
  background: var(--button-danger-bg);
  border-color: var(--button-danger-border);
  color: var(--button-danger-fg);
}

.inline-confirm {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

/* composer-integrated prompt shelf */
.modal--plan {
  max-width: 560px;
}

.prompt-shelf {
  max-width: var(--maxw);
  margin: 0 auto 10px;
  animation: shelf-in var(--dur-slow) var(--ease-out) both;
}
.todo-exit {
  animation: shelf-in 240ms 900ms ease reverse both;
}
@keyframes shelf-in {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
}
/* Composer host under a decision surface: stays mounted for draft caches. */
.composer-decision-host {
  display: block;
  min-width: 0;
}
.composer-decision-host--hidden,
.composer-decision-host[hidden] {
  display: none !important;
}
.composer-decision-host--footprint-hidden {
  visibility: hidden;
  pointer-events: none;
}
.footer--navigation-hidden {
  visibility: hidden;
  pointer-events: none;
}
.prompt-shelf__card {
  display: grid;
  gap: 8px;
  border: 1px solid transparent;
  border-radius: 20px;
  background: rgba(64, 64, 64, 0.06);
  padding: 7px 12px;
  outline: none;
}

.prompt-shelf__card--collapsible {
  cursor: pointer;
}

.prompt-shelf__card--collapsed .prompt-shelf__content > :not(.prompt-shelf__header) {
  display: none;
}

/* Shared harness-style decision surface. Ask adds its own fields and pager;
   every other PromptShelf keeps its domain controls inside this same visual
   frame so approvals, forms, and MCP interactions read as one product. */
.prompt-shelf--harness .prompt-shelf__card {
  border-radius: 20px;
  padding: 8px 12px 10px;
  background: var(--bg-elev);
  border-color: color-mix(in srgb, var(--accent) 34%, var(--border-soft));
}
.prompt-shelf--harness .prompt-shelf__header {
  align-items: center;
  gap: 16px;
  padding: 10px 4px 12px;
}
.prompt-shelf--harness .prompt-shelf__heading {
  font-size: 16px;
  font-weight: 650;
}
.prompt-shelf--harness .prompt-shelf__meta {
  font-size: 14px;
}
.prompt-shelf--harness .prompt-shelf__header-actions {
  gap: 8px;
}
.prompt-shelf--harness .prompt-shelf__header-button {
  min-height: 32px;
  border-radius: 999px;
  padding: 0 10px;
}
.prompt-shelf--harness.prompt-shelf--decision .prompt-shelf__actions {
  gap: 6px;
}
.prompt-shelf--harness.prompt-shelf--decision .prompt-action {
  min-height: 38px;
  height: 38px;
  border-radius: 10px;
  padding: 5px 10px;
}
.prompt-shelf--harness .prompt-shelf__footer {
  padding-top: 10px;
  margin-top: 4px;
}
.prompt-shelf--harness .decision-confirm-bar {
  gap: 10px;
}

/* Todo shelf: header actions (collapse/close) appear on card hover/focus. */
.prompt-shelf--todo .prompt-shelf__header-actions {
  opacity: 0;
  transition: opacity 0.12s ease;
}
.prompt-shelf--todo .prompt-shelf__card--collapsed {
  height: 48px;
  min-height: 48px;
  padding: 4px 10px;
  border-radius: 14px;
  box-sizing: border-box;
}
.prompt-shelf--todo .prompt-shelf__card--collapsed .prompt-shelf__header {
  gap: 10px;
  padding: 4px 2px;
}
.prompt-shelf--todo .prompt-shelf__card--collapsed .prompt-shelf__heading,
.prompt-shelf--todo .prompt-shelf__card--collapsed .prompt-shelf__meta {
  font-size: 12px;
}
.prompt-shelf--todo .prompt-shelf__card--collapsed .prompt-shelf__header-button {
  min-height: 26px;
  padding: 0 8px;
}

.prompt-shelf--todo:hover .prompt-shelf__header-actions,
.prompt-shelf--todo .prompt-shelf__header-button:focus-visible {
  opacity: 1;
}

:root[data-theme="light"] .prompt-shelf__card,
:root[data-theme="light"][data-theme-style] .prompt-shelf__card {
  background: rgba(64, 64, 64, 0.05);
}

:root[data-theme="dark"] .prompt-shelf__card,
:root[data-theme="dark"][data-theme-style] .prompt-shelf__card {
  background: rgba(255, 255, 255, 0.08);
}
.prompt-shelf__content {
  display: grid;
  min-width: 0;
  gap: 8px;
}
.prompt-shelf__card:focus-visible {
  border-color: color-mix(in srgb, var(--fg-faint) 40%, transparent);
  box-shadow: none;
}
.prompt-shelf__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}
.prompt-shelf__copy {
  min-width: 0;
  flex: 1;
  display: grid;
  gap: 4px;
}
.prompt-shelf__title {
  display: flex;
  align-items: center;
  flex-wrap: nowrap;
  gap: 6px;
  min-width: 0;
  max-width: 100%;
  color: var(--fg);
  font-size: 12.5px;
  font-weight: 650;
  line-height: 1.25;
}
.prompt-shelf__heading {
  flex: 0 0 auto;
  min-width: 0;
}
.prompt-shelf__badges {
  display: flex;
  flex-wrap: nowrap;
  gap: 6px;
  flex: 0 0 auto;
  min-width: 0;
}
.prompt-shelf__badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  border: 1px solid var(--border-soft);
  border-radius: 999px;
  background: var(--bg-soft);
  color: var(--fg-faint);
  font-size: 11px;
  font-weight: 600;
  line-height: 1.2;
}
.prompt-shelf__badge--amber {
  border-color: color-mix(in srgb, var(--warn, #f59e0b) 42%, var(--border-soft));
  background: color-mix(in srgb, var(--warn, #f59e0b) 14%, var(--bg-soft));
  color: color-mix(in srgb, var(--warn, #f59e0b) 72%, var(--fg));
}
.prompt-shelf__badge--danger {
  border-color: color-mix(in srgb, var(--err) 36%, var(--border-soft));
  background: color-mix(in srgb, var(--err) 10%, var(--bg-soft));
  color: color-mix(in srgb, var(--err) 70%, var(--fg));
}
.prompt-shelf__meta {
  flex: 0 1 auto;
  min-width: 0;
  align-self: center;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--fg-dim);
  font-size: 11.5px;
  font-weight: 500;
  line-height: 1.25;
  padding-left: 8px;
  border-left: 1px solid var(--border-soft);
  overflow-wrap: normal;
}
.prompt-shelf__header-actions,
.prompt-shelf__quick-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: flex-end;
}
.prompt-shelf__header-button {
  --wails-draggable: no-drag;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 24px;
  padding: 0 8px;
  border: 1px solid var(--border-soft);
  border-radius: 999px;
  background: var(--bg-soft);
  color: var(--fg-dim);
  cursor: pointer;
  font: inherit;
  font-size: 11px;
  line-height: 1.2;
  white-space: nowrap;
}
.prompt-shelf__header-button:hover {
  border-color: var(--fg-faint);
  background: var(--bg-elev-2);
  color: var(--fg);
}
.prompt-shelf__header-button:focus-visible {
  outline: none;
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 10%, var(--bg-elev));
  color: var(--fg);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 40%, transparent);
}
.prompt-shelf__body {
  display: grid;
  gap: 8px;
}
.prompt-shelf__actions {
  display: grid;
  grid-template-columns: 1fr;
  gap: 6px;
}
.prompt-action {
  --wails-draggable: no-drag;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  width: 100%;
  border: 1px solid var(--border-soft);
  border-radius: 8px;
  background: var(--bg-soft);
  color: var(--fg);
  cursor: pointer;
  font: inherit;
  font-size: 11.5px;
  line-height: 1.35;
  padding: 7px 9px;
  text-align: left;
  transition: border-color 0.12s, background 0.12s;
}
.prompt-action:disabled {
  cursor: default;
  opacity: 0.48;
}
.prompt-action:hover {
  border-color: var(--fg-faint);
  background: var(--bg-elev-2);
}
.prompt-action:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 45%, transparent);
}
.prompt-action:disabled:hover {
  border-color: var(--border-soft);
  background: var(--bg-soft);
}
.prompt-action--selected {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--border));
  background: var(--accent-soft);
}
.prompt-action--selected:hover {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 18%, var(--bg-elev));
}
/* Keyboard cursor only — not a committed multi-select answer. */
.prompt-action--active:not(.prompt-action--selected) {
  border-color: color-mix(in srgb, var(--accent) 40%, var(--border));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 35%, transparent);
}
.prompt-action--active.prompt-action--selected {
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 50%, transparent);
}
.prompt-action--danger:not(.prompt-action--selected) {
  border-color: color-mix(in srgb, var(--err) 22%, var(--border-soft));
}
.prompt-action--danger.prompt-action--selected {
  border-color: color-mix(in srgb, var(--err) 50%, var(--border));
  background: color-mix(in srgb, var(--err) 12%, var(--bg-elev));
}
.prompt-action--danger.prompt-action--selected .prompt-action__key {
  border-color: var(--err);
  background: var(--err);
  color: #fff;
}
.prompt-shelf__footer {
  border-top: 1px solid var(--border-soft);
  padding-top: 8px;
  margin-top: 2px;
}
.decision-confirm-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}
.decision-confirm-bar__secondary,
.runtime-decision-footer__secondary {
  flex: 0 0 auto;
  color: var(--fg-dim);
  background: transparent;
  border-color: transparent;
}
.decision-confirm-bar__secondary:hover:not(:disabled),
.runtime-decision-footer__secondary:hover:not(:disabled) {
  color: var(--fg);
  background: var(--bg-soft);
  border-color: var(--border-soft);
}
.decision-confirm-bar__hint {
  min-width: 0;
  flex: 1;
  color: var(--fg-faint);
  font-size: 11px;
  line-height: 1.35;
}
.decision-confirm-bar__confirm {
  flex: 0 0 auto;
  min-width: 88px;
}
/* Unified decision surface: vertical full-width options, sticky footer, and
/* Unified decision surface: vertical full-width options, sticky footer, and
   one bounded content scroller. Never collapses to horizontal pills. */
.prompt-shelf--decision .prompt-shelf__card {
  grid-template-rows: minmax(0, 1fr) auto;
  gap: 6px;
  max-height: min(62vh, 560px);
  padding: 8px 10px;
  overflow: hidden;
  border-color: color-mix(in srgb, var(--accent) 28%, var(--border));
}
.prompt-shelf--decision .prompt-shelf__content {
  min-height: 0;
  align-content: start;
  overflow: auto;
  overscroll-behavior: contain;
  padding-right: 2px;
}
.prompt-shelf--decision .prompt-shelf__header {
  align-items: flex-start;
}
.prompt-shelf--decision .prompt-shelf__meta {
  overflow: visible;
  text-overflow: clip;
  white-space: normal;
  overflow-wrap: anywhere;
}
.prompt-shelf--decision .prompt-shelf__body {
  max-height: none;
  overflow: visible;
}
.prompt-shelf--decision .prompt-shelf__actions {
  display: grid !important;
  grid-template-columns: 1fr !important;
  grid-auto-rows: max-content;
  align-content: start;
  gap: 6px;
  max-height: none;
  overflow: visible;
}
.prompt-shelf--decision .prompt-shelf__actions > .prompt-action-row {
  width: 100%;
}
.prompt-shelf--decision .prompt-shelf__actions .prompt-action {
  width: 100% !important;
  min-height: 38px;
  height: 38px;
  align-items: center;
  border-radius: 8px !important;
  padding: 5px 8px;
  overflow: hidden;
  white-space: nowrap !important;
}
.prompt-shelf--decision .prompt-shelf__actions .prompt-action__key {
  margin-top: 0;
}
.prompt-shelf--decision .prompt-shelf__actions .prompt-action__copy {
  display: grid !important;
  grid-template-columns: fit-content(44%) minmax(0, 1fr);
  align-items: baseline;
  gap: 2px 10px;
}
.prompt-shelf--decision .prompt-shelf__actions .prompt-action:not(.prompt-action--descriptive) .prompt-action__copy {
  grid-template-columns: minmax(0, 1fr);
}
.prompt-shelf--decision .prompt-shelf__actions .prompt-action__label,
.prompt-shelf--decision .prompt-shelf__actions .prompt-action__desc {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap !important;
  text-overflow: ellipsis;
}
.prompt-shelf--decision .prompt-shelf__actions .prompt-action__label {
  font-weight: 620;
}
.prompt-shelf--decision .prompt-shelf__actions .prompt-action__desc {
  line-height: 1.4;
}
.prompt-shelf--decision .prompt-shelf__actions .prompt-action__desc {
  display: block;
}
.prompt-shelf--recovery-approval {
  max-width: min(var(--maxw), 760px);
}
.prompt-shelf--recovery-approval .prompt-shelf__card {
  border-color: var(--border);
}
.prompt-shelf--recovery-approval .prompt-action__key {
  border-color: transparent;
  background: transparent;
  color: var(--fg-faint);
}
.prompt-shelf--recovery-approval .prompt-action--selected .prompt-action__key {
  border-color: transparent;
  background: transparent;
  color: var(--accent);
}
.recovery-summary {
  display: grid;
  gap: 7px;
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--warning, #f59e0b) 28%, var(--border-soft));
  border-radius: 8px;
  background: color-mix(in srgb, var(--warning, #f59e0b) 7%, var(--bg-soft));
}
.recovery-summary__reason,
.recovery-summary__action {
  margin: 0;
}
.recovery-summary__reason {
  color: var(--fg);
  font-size: 12.5px;
  font-weight: 600;
  line-height: 1.45;
}
.recovery-summary__action {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 8px;
  align-items: baseline;
  color: var(--fg-dim);
  font-size: 11px;
  line-height: 1.45;
}
.recovery-summary__action span {
  color: var(--fg-faint);
  white-space: nowrap;
}
.recovery-summary__action code {
  min-width: 0;
  color: var(--fg-dim);
  font-family: var(--mono);
  overflow-wrap: anywhere;
}
.plan-change-delta {
  display: grid;
  gap: 8px;
  max-height: min(240px, 32vh);
  overflow: auto;
  padding: 10px 12px;
  border: 1px solid var(--border-soft);
  border-radius: 8px;
  background: var(--bg-soft);
}
.plan-change-delta__title {
  color: var(--fg);
  font-size: 12px;
  font-weight: 650;
}
.plan-change-delta__group {
  display: grid;
  gap: 4px;
