}
.hljs-keyword,
.hljs-selector-tag,
.hljs-literal,
.hljs-section,
.hljs-doctag,
.hljs-type,
.hljs-name,
.hljs-strong {
  color: var(--hl-keyword);
}
.hljs-string,
.hljs-regexp,
.hljs-attribute,
.hljs-meta .hljs-string {
  color: var(--hl-string);
}
.hljs-addition {
  color: var(--add-fg);
}
.hljs-deletion {
  color: var(--del-fg);
}
.hljs-number,
.hljs-symbol,
.hljs-bullet,
.hljs-link,
.hljs-selector-attr,
.hljs-selector-pseudo {
  color: var(--hl-number);
}
.hljs-title,
.hljs-title.function_,
.hljs-section .hljs-title {
  color: var(--hl-func);
}
.hljs-class .hljs-title,
.hljs-title.class_,
.hljs-built_in,
.hljs-attr {
  color: var(--hl-type);
}
.hljs-variable,
.hljs-template-variable,
.hljs-property,
.hljs-params,
.hljs-selector-id,
.hljs-selector-class {
  color: var(--hl-builtin);
}
.hljs-meta,
.hljs-comment .hljs-doctag {
  color: var(--hl-meta);
}
.hljs-emphasis {
  font-style: italic;
}
.hljs-strong {
  font-weight: 600;
}

/* ── scrollbars ──────────────────────────────────────────────────────────── */
* {
  scrollbar-width: thin;
  scrollbar-color: var(--scrollbar-thumb) var(--scrollbar-track);
}

::-webkit-scrollbar {
  width: var(--scrollbar-size);
  height: var(--scrollbar-size);
}
::-webkit-scrollbar-thumb {
  background: var(--scrollbar-thumb);
  border-radius: 999px;
  border: 2px solid transparent;
  background-clip: padding-box;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--scrollbar-thumb-hover);
  background-clip: padding-box;
}
::-webkit-scrollbar-thumb:active {
  background: var(--scrollbar-thumb-active);
  background-clip: padding-box;
}
::-webkit-scrollbar-track {
  background: var(--scrollbar-track);
}
::-webkit-scrollbar-corner {
  background: var(--scrollbar-corner);
}

/* ── workspace side panel ────────────────────────────────────────────────── */
.workspace-panel {
  --workspace-tree-width: 280px;
  --workspace-preview-min-width: 360px;
  position: relative;
  min-width: 0;
  min-height: 0;
  display: grid;
  /* Preview on the left, file tree on the right (user preference). */
  grid-template-columns: minmax(var(--workspace-preview-min-width), 1fr) var(--workspace-tree-width);
  grid-template-rows: minmax(0, 1fr);
  height: 100%;
  background: var(--workspace-preview-bg);
  border-left: 1px solid var(--border-soft);
}
.workspace-panel--embedded {
  border-left: none;
}
.workspace-panel--tree-hidden {
  grid-template-columns: minmax(0, 1fr);
}
.workspace-panel--tree-hidden .workspace-files {
  display: none;
}
.workspace-panel--tree-hidden .workspace-preview {
  grid-column: 1;
}
.workspace-panel--detail-only {
  grid-template-columns: minmax(0, 1fr);
}
.workspace-panel--detail-only .workspace-files {
  display: none;
}
.workspace-panel--detail-only .workspace-preview {
  grid-column: 1;
}
.workspace-panel--preview-hidden {
  grid-template-columns: minmax(0, 1fr);
}
.workspace-panel--preview-hidden .workspace-files {
  grid-column: 1;
  background: var(--workspace-files-bg);
  border-right: none;
}
.workspace-preview,
.workspace-files {
  min-width: 0;
  min-height: 0;
}
.workspace-preview {
  grid-row: 1;
  grid-column: 1;
  display: flex;
  flex-direction: column;
  background: var(--workspace-preview-bg);
}
.workspace-panel--embedded.workspace-panel--split-preview .workspace-preview {
  border-left: 0;
}
.workspace-tree-resizer {
  --wails-draggable: no-drag;
  position: absolute;
  top: 0;
  /* Tree sits on the right after the files/preview swap, so the resizer
     rides the tree's left edge. */
  left: calc(100% - var(--workspace-tree-width) - 4px);
  bottom: 0;
  z-index: var(--z-layout-resizer-active);
  width: 8px;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: col-resize;
  touch-action: none;
}
.workspace-tree-resizer::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 1px;
  transform: translateX(-50%);
  background: transparent;
  transition: background 0.12s, box-shadow 0.12s;
}
.workspace-tree-resizer:hover::after,
.workspace-tree-resizer:focus-visible::after,
.workspace-panel--tree-resizing .workspace-tree-resizer::after {
  background: var(--accent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 24%, transparent);
}
.workspace-panel--tree-resizing,
.workspace-panel--tree-resizing * {
  cursor: col-resize !important;
  user-select: none;
}
.workspace-preview__head {
  flex: 0 0 auto;
  height: 50px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
  border-bottom: 1px solid var(--border-soft);
}
.workspace-panel--embedded .workspace-preview__head {
  height: 42px;
  gap: 6px;
  padding: 0 8px 0 10px;
}
.workspace-current-file {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  height: 100%;
}
.workspace-current-file__icon {
  flex: 0 0 auto;
  color: var(--fg-faint);
}
.workspace-current-file__icon.workspace-file-icon,
.workspace-current-file__icon .workspace-file-icon {
  width: 18px;
  height: 20px;
  flex: 0 0 18px;
  font-size: 20px;
}
.workspace-current-file__text {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 2px;
}
.workspace-current-file__name {
  display: block;
  min-width: 0;
  overflow: hidden;
  color: var(--fg);
  font-size: 12.5px;
  font-weight: 620;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.workspace-current-file__path {
  display: flex;
  align-items: center;
  min-width: 0;
  overflow: hidden;
  color: var(--fg-faint);
  font-size: 11px;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.workspace-current-file__crumb {
  display: inline-flex;
  align-items: center;
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  line-height: 1.15;
}
.workspace-current-file__crumb-sep {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  margin: 0 3px;
  color: var(--fg-faint);
  font-size: 16px;
  line-height: 0;
}
.workspace-current-file__recent {
  --wails-draggable: no-drag;
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  color: var(--fg-faint);
}
.workspace-current-file__recent:hover,
.workspace-current-file__recent--open {
  border-color: var(--border-soft);
  background: var(--bg-soft);
  color: var(--fg);
}
.workspace-current-file__recent--open svg {
  transform: rotate(180deg);
}
.workspace-preview__window-actions {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 6px;
}
.workspace-recent-menu {
  width: min(260px, calc(100vw - 24px));
  padding: 7px;
  border: 1px solid var(--border);
  border-radius: 9px;
  box-shadow: 0 14px 34px rgba(0, 0, 0, 0.28);
}
.workspace-recent-menu__title {
  padding: 3px 6px 7px;
  color: var(--fg-faint);
  font-size: 11px;
  font-weight: 620;
}
.workspace-recent-menu__list {
  display: grid;
  gap: 3px;
}
.workspace-recent-menu__item {
  width: 100%;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 8px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--fg-dim);
  font: inherit;
  text-align: left;
}
.workspace-recent-menu__item:hover,
.workspace-recent-menu__item--active {
  background: var(--bg-soft);
  color: var(--fg);
}
.workspace-recent-menu__item svg {
  flex: 0 0 auto;
  color: var(--fg-faint);
}
.workspace-recent-menu__item > span {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.workspace-recent-menu__name,
.workspace-recent-menu__path {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.workspace-recent-menu__name {
  color: var(--fg);
  font-size: 12.5px;
  font-weight: 560;
}
.workspace-recent-menu__path {
  color: var(--fg-faint);
  font-size: 11px;
}
.workspace-iconbtn {
  --wails-draggable: no-drag;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border: none;
  border-radius: 7px;
  background: transparent;
  color: var(--fg-faint);
  transition: color 0.12s, background 0.12s;
}
.workspace-iconbtn:hover {
  color: var(--fg);
  background: var(--bg-soft);
}
.workspace-iconbtn:disabled {
  opacity: 0.4;
  cursor: default;
}
.workspace-iconbtn:disabled:hover {
  color: var(--fg-faint);
  background: transparent;
}
.workspace-iconbtn--on {
  color: var(--fg-dim);
}
.workspace-preview__body {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  padding: 16px 18px 24px;
  background: var(--workspace-preview-bg);
}
.workspace-panel--embedded .workspace-preview__body {
  padding: 12px 12px 18px;
}
.workspace-preview__body--code {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  padding: 0;
}
.workspace-panel--embedded .workspace-preview__body--code {
  padding: 0;
}
.workspace-preview__body--code .workspace-note {
  flex: 0 0 auto;
  margin: 10px 14px 8px;
}
.workspace-preview__body--code .code-block {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  display: flex;
  width: 100%;
  max-width: none;
}
.workspace-preview__body--code .code-block__wrap {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  display: flex;
  width: 100%;
  max-width: none;
}
.workspace-preview__body--code .code {
  /* max-height: none overrides .code--scroll-y's min(60vh, 28rem) so the
     preview fills its container even for virtual-scrolled (large) files
     that opt into the .code--scroll-y class */
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  max-width: none;
  max-height: none;
  margin: 0;
  border: 0;
  border-radius: 0;
  overflow: auto;
}
/* line-numbered code fills the preview body */
.workspace-preview__body--code .code--lines {
  padding: 0;
  border-radius: 0;
}
.workspace-preview__body--code .code-block__wrap {
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.workspace-preview__body--code .code-search {
  position: static;
  z-index: var(--z-local-handle);
  flex: 0 0 auto;
  flex-wrap: wrap;
  box-sizing: border-box;
  width: 100%;
  max-width: none;
  min-width: 0;
  padding: 5px 8px;
  border-width: 0 0 1px;
  border-radius: 0;
  box-shadow: none;
}
.workspace-preview__body .code-block,
.workspace-preview__body .code {
  margin-top: 0;
}
.workspace-preview__body .md,
.workspace-preview__body .code-block,
.workspace-preview__body .code,
.workspace-preview__body .md table {
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
}
.workspace-preview__body .code {
  min-width: 0;
}
.workspace-media {
  box-sizing: border-box;
  width: 100%;
}
.workspace-media--image {
  display: flex;
  align-items: flex-start;
  justify-content: center;
  min-height: 100%;
}
.workspace-media--image img {
  display: block;
  max-width: 100%;
  height: auto;
  object-fit: contain;
}
.workspace-media--pdf {
  display: block;
  height: 100%;
  min-height: 520px;
  border: 0;
  background: var(--bg);
}
.workspace-note {
  margin-bottom: 10px;
  padding: 6px 9px;
  border: 1px solid var(--border-soft);
  border-radius: 7px;
  background: var(--bg-soft);
  color: var(--fg-dim);
  font-size: 12px;
}
.workspace-note--warning {
  background: color-mix(in srgb, var(--warn) 10%, var(--bg-soft));
  color: var(--warn);
}
.workspace-note--compact {
  margin: 0 10px 8px;
  padding: 6px 8px;
  font-size: 11.5px;
}
.workspace-completion-summary--attention {
  border-color: color-mix(in srgb, var(--warn) 35%, var(--border-soft));
}
.workspace-completion-summary {
  cursor: default;
}
.workspace-completion-summary__head,
.workspace-completion-summary__details {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 8px;
}
.workspace-completion-summary__title {
  margin: 0 auto 0 0;
  color: var(--fg);
  font: inherit;
  font-weight: 650;
}
.workspace-completion-summary__details {
  margin-top: 4px;
}
.turn-result-summary { display: grid; gap: 6px; margin-top: 6px; color: var(--fg); }
.turn-result-summary__checks { display: flex; align-items: center; gap: 6px; color: var(--fg-dim); }
.turn-result-summary__checks svg { flex: 0 0 auto; }
.turn-result-added, .turn-result-summary__checks--passed { color: var(--ok); }
.turn-result-removed, .turn-result-summary__checks--failed { color: var(--danger); }
.turn-result-warning, .turn-result-summary__checks--stale, .turn-result-summary__checks--interrupted { color: var(--warn); }
.workspace-turn-result { min-width: 0; padding: 16px; color: var(--fg); font-size: 12px; }
.workspace-turn-result__head, .workspace-turn-result__tabs { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.workspace-turn-result__head { justify-content: space-between; }
.workspace-turn-result__tabs [aria-pressed="true"] { background: var(--bg-soft); color: var(--accent); }
.workspace-turn-result__label, .turn-check-details__footnote { color: var(--fg-dim); }
.turn-file-list { margin-top: 14px; border: 1px solid var(--border-soft); border-radius: 6px; overflow: hidden; }
.turn-file-list:empty { display: none; }
.turn-file-list__entry { display: flex; width: 100%; gap: 12px; justify-content: space-between; padding: 10px; border: 0; border-bottom: 1px solid var(--border-soft); background: transparent; color: var(--fg); text-align: left; font: inherit; cursor: pointer; }
.turn-file-list__entry:last-child { border-bottom: 0; }
.turn-file-list__entry > span:first-child { min-width: 0; overflow-wrap: anywhere; }
.turn-file-list__entry > span:last-child { flex-shrink: 0; }
.turn-file-list__entry[aria-pressed="true"] { background: var(--bg-soft); }
.turn-file-list__entry:disabled { color: var(--fg-dim); cursor: default; }
.turn-file-diff { min-width: 0; margin-top: 16px; }
.turn-file-diff h4 { overflow-wrap: anywhere; margin: 0 0 8px; }
.turn-check-details { min-width: 0; width: 100%; }
.turn-check-details__status { color: var(--fg); }
.turn-check-details__entry { border: 1px solid var(--border-soft); border-radius: 6px; padding: 10px; margin: 8px 0; }
.turn-check-details__head { display: flex; flex-wrap: wrap; gap: 6px 12px; justify-content: space-between; color: var(--fg); }
.turn-check-details__head code { min-width: 0; overflow-wrap: anywhere; }
.turn-check-details__gaps { padding-left: 18px; overflow-wrap: anywhere; }
.turn-check-log { margin-top: 8px; }
.turn-check-log summary { width: fit-content; cursor: pointer; color: var(--accent); }
.turn-check-log pre { max-height: 320px; overflow: auto; white-space: pre-wrap; overflow-wrap: anywhere; padding: 10px; background: var(--bg-soft); border-radius: 4px; color: var(--fg); }
.floating-menu {
  --wails-draggable: no-drag;
  position: fixed;
  z-index: var(--z-floating-menu);
  min-width: 148px;
  padding: 5px;
  border: 1px solid var(--border);
  border-radius: 8px;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.36);
  transform-origin: top left;
  animation: menu-pop-in var(--dur-base) var(--ease-out) both;
}
.floating-menu button {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 7px 9px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--fg);
  font: inherit;
  font-size: 12.5px;
}
.floating-menu button:hover {
  background: var(--bg-soft);
}
.floating-menu__separator {
  height: 1px;
  margin: 5px 4px;
  background: var(--border-soft);
}
.tooltip-trigger {
  display: inline-flex;
  min-width: 0;
}
.tooltip-trigger--fill {
  display: flex;
  width: 100%;
}
.tooltip-trigger--block {
  display: flex;
}
.tooltip {
  --wails-draggable: no-drag;
  --tooltip-arrow-x: 50%;
  --tooltip-arrow-y: 50%;
  position: fixed;
  z-index: var(--z-tooltip);
  max-width: min(320px, calc(100vw - 16px));
  padding: 6px 8px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--bg-elev);
  color: var(--fg);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.28);
  font-size: 12px;
  line-height: 1.35;
  overflow-wrap: anywhere;
  pointer-events: none;
  white-space: pre-line;
  animation: tooltip-in var(--dur-fast) var(--ease-out) both;
}
.tooltip--top {
  --tooltip-from-y: var(--motion-rise);
  --tooltip-from-x: 0;
}
.tooltip--bottom {
  --tooltip-from-y: calc(-1 * var(--motion-rise));
  --tooltip-from-x: 0;
}
.tooltip--left {
  --tooltip-from-x: var(--motion-rise);
  --tooltip-from-y: 0;
}
.tooltip--right {
  --tooltip-from-x: calc(-1 * var(--motion-rise));
  --tooltip-from-y: 0;
}
@keyframes tooltip-in {
  from {
    opacity: 0;
    transform: translate(var(--tooltip-from-x, 0), var(--tooltip-from-y, 0));
  }
  to {
    opacity: 1;
    transform: translate(0, 0);
  }
}
.tooltip::before {
  content: "";
  position: absolute;
  width: 8px;
  height: 8px;
  border: 1px solid var(--border);
  background: var(--bg-elev);
  transform: rotate(45deg);
}
.tooltip--top::before {
  left: calc(var(--tooltip-arrow-x) - 4px);
  bottom: -5px;
  border-left: 0;
  border-top: 0;
}
.tooltip--bottom::before {
  left: calc(var(--tooltip-arrow-x) - 4px);
  top: -5px;
  border-right: 0;
  border-bottom: 0;
}
.tooltip--left::before {
  right: -5px;
  top: calc(var(--tooltip-arrow-y) - 4px);
  border-left: 0;
  border-bottom: 0;
}
.tooltip--right::before {
  left: -5px;
  top: calc(var(--tooltip-arrow-y) - 4px);
  border-right: 0;
  border-top: 0;
}
.tooltip .md {
  white-space: normal;
  font-size: inherit;
  line-height: inherit;
}
.tooltip .md pre {
  max-height: 240px;
  overflow: auto;
  font-size: 11px;
}
/* past:chats hover preview (PR-C2). Inherits colors from the .tooltip container
/* past:chats hover preview (PR-C2). Inherits colors from the .tooltip container
   (--fg / --fg-dim / --fg-faint / --border / --bg-elev) and only adjusts layout. */
.past-chat-hover {
  display: flex;
  flex-direction: column;
  gap: 3px;
  max-width: 300px;
}
.past-chat-hover__title {
  font-weight: 600;
  color: var(--fg);
  word-break: break-word;
}
.past-chat-hover__preview {
  color: var(--fg-dim);
  word-break: break-word;
  max-height: 96px;
  overflow: hidden;
  /* fade the cut so long previews don't look amputated */
  -webkit-mask-image: linear-gradient(to bottom, #000 70%, transparent 100%);
  mask-image: linear-gradient(to bottom, #000 70%, transparent 100%);
}
.past-chat-hover__meta {
  color: var(--fg-faint);
  font-size: 11px;
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
.past-chat-hover__path {
  color: var(--fg-faint);
  font-size: 11px;
  word-break: break-all;
  max-height: 32px;
  overflow: hidden;
}
.workspace-empty {
  padding: 18px 0;
  color: var(--fg-faint);
  font-size: 13px;
}
.workspace-empty--error {
  color: var(--err);
}
.workspace-files {
  grid-row: 1;
  grid-column: 2;
  display: flex;
  flex-direction: column;
  background: var(--workspace-files-bg);
  border-right: 1px solid var(--border-soft);
}
.workspace-files__tools {
  flex: 0 0 auto;
  height: 42px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
  padding: 7px 8px 3px;
}
.workspace-files__tools--embedded {
  height: 34px;
  overflow: visible;
  justify-content: flex-start;
  padding: 6px 10px 0;
}
.workspace-watch-status {
  color: var(--text-muted, var(--fg-faint));
  font-size: 18px;
  line-height: 1;
  cursor: help;
}
.workspace-iconbtn[aria-busy="true"] svg {
  animation: spin 0.8s linear infinite;
}
.workspace-files__tabs {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  padding: 3px;
  border-radius: 8px;
  background: var(--bg);
  border: 1px solid var(--border-soft);
}
.workspace-files__tab {
  --wails-draggable: no-drag;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-width: 0;
  height: 24px;
  padding: 0 8px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--fg-faint);
  font: inherit;
