}

/* ── memory drawer ───────────────────────────────────────────────────────── */
.drawer-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  justify-content: flex-end;
  z-index: var(--z-drawer-backdrop);
  animation: backdrop-in var(--dur-base) var(--ease-out) both;
}
@keyframes backdrop-in {
  from {
    opacity: 0;
  }
}
@keyframes backdrop-out {
  to {
    opacity: 0;
  }
}
/* Overlays that opt into exit animation via useMountTransition flip
/* Overlays that opt into exit animation via useMountTransition flip
 * data-state="closing" before unmount; reverse the backdrop fade. */
.drawer-backdrop[data-state="closing"] {
  animation: backdrop-out var(--dur-base) var(--ease-out) both;
}
.drawer-backdrop--subtle {
  background: rgba(0, 0, 0, 0.16);
}

/* ── command palette (⌘K) — centered modal over a dimmed backdrop ─────────── */
.drawer-backdrop:has(> .palette) {
  justify-content: center;
  align-items: flex-start;
  padding-top: 12vh;
  background: rgba(0, 0, 0, 0.42);
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
}
.palette {
  width: min(620px, 92vw);
  max-height: 70vh;
  display: flex;
  flex-direction: column;
  background: var(--bg-elev);
  border: 1px solid var(--border-2, var(--border));
  border-radius: 14px;
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.5);
  overflow: hidden;
  animation: palette-in 0.16s cubic-bezier(0.34, 1.4, 0.5, 1);
}
.palette[data-state="closing"] {
  animation: palette-out var(--dur-base) var(--ease-out) both;
}
@keyframes palette-in {
  from {
    transform: translateY(-12px) scale(0.97);
    opacity: 0;
  }
}
@keyframes palette-out {
  to {
    transform: translateY(-8px) scale(0.98);
    opacity: 0;
  }
}
.palette__inputrow {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--border);
}
.palette__search-icon {
  flex: none;
  color: var(--fg-faint);
}
.palette__input {
  flex: 1;
  min-width: 0;
  border: none;
  background: transparent;
  color: var(--fg);
  font: inherit;
  font-size: 15px;
  outline: none;
}
.palette__input::placeholder {
  color: var(--fg-faint);
}
.palette__esc {
  flex: none;
  display: inline-flex;
  align-items: center;
  font-family: var(--mono);
  font-size: 10px;
  color: var(--fg-faint);
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 5px;
  padding: 3px 6px;
  line-height: 1;
  cursor: pointer;
}
.palette__esc:hover {
  color: var(--fg);
  background: var(--bg-soft);
}
.palette__esc:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.palette__list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 8px;
}
.palette__empty {
  padding: 28px 12px;
  text-align: center;
  color: var(--fg-faint);
  font-size: 13px;
}
.palette__group + .palette__group {
  margin-top: 6px;
}
.palette__group-title {
  padding: 8px 12px 4px;
  font-size: 10.5px;
  font-weight: 650;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--fg-faint);
}
.palette__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(90px, 1fr));
  gap: 6px;
  padding: 4px 12px 8px;
}
.palette__chip {
  --wails-draggable: no-drag;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  padding: 10px 6px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--fg);
  font: inherit;
  font-size: 11.5px;
  text-align: center;
  cursor: pointer;
}
.palette__chip:hover,
.palette__chip--on {
  background: var(--accent-soft);
}
.palette__chip-icon {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 6px;
  background: var(--bg-soft);
  color: var(--accent);
}
.palette__chip-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
}
.palette__item {
  --wails-draggable: no-drag;
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 10px 12px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--fg);
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.palette__item--on {
  background: var(--accent-soft);
}
.palette__item:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}
.palette__item-icon {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  flex: 0 0 30px;
  border-radius: 8px;
  background: var(--bg-soft);
  color: var(--accent);
}
.palette__body {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.palette__title {
  display: block;
  font-size: 13.5px;
  font-weight: 500;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.palette__item--on .palette__title {
  color: var(--accent);
}
.palette__hint {
  display: flex;
  align-items: baseline;
  gap: 8px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-content-family);
  font-size: 11.5px;
  line-height: 1.35;
  color: var(--fg-faint);
}
.palette__hint-text {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.palette__meta {
  flex: none;
  margin-left: auto;
}
.palette__badge {
  flex: none;
  min-width: 2.5em;
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.palette__foot {
  flex: none;
  display: flex;
  gap: 16px;
  padding: 9px 16px;
  border-top: 1px solid var(--border);
  font-size: 11px;
  color: var(--fg-faint);
}
.palette__foot kbd {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--fg-dim);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 2px 5px;
  margin-right: 3px;
}
.drawer {
  position: relative;
  width: min(var(--drawer-width, 440px), 92vw);
  height: 100%;
  background: var(--bg-elev);
  border-left: 1px solid var(--border);
  box-shadow: -18px 0 48px rgba(0, 0, 0, 0.46);
  display: flex;
  flex-direction: column;
  animation: drawer-in var(--dur-slow) var(--ease-out) both;
}
.drawer--wide {
  width: min(var(--drawer-width, 720px), 94vw);
}
.drawer-resizer {
  --wails-draggable: no-drag;
  position: absolute;
  top: 0;
  bottom: 0;
  left: -4px;
  z-index: var(--z-local-handle);
  width: 8px;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: col-resize;
}
.drawer-resizer::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 1px;
  transform: translateX(-50%);
  background: transparent;
  transition: background 0.12s, box-shadow 0.12s;
}
.drawer-resizer:hover::after,
.drawer-resizer:focus-visible::after,
.drawer--resizing .drawer-resizer::after {
  background: var(--accent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 24%, transparent);
}
.drawer--resizing,
.drawer--resizing * {
  cursor: col-resize !important;
  user-select: none;
}
@keyframes drawer-in {
  from {
    transform: translateX(24px);
    opacity: 0;
  }
}
@keyframes drawer-out {
  to {
    transform: translateX(24px);
    opacity: 0;
  }
}
.drawer[data-state="closing"] {
  animation: drawer-out var(--dur-slow) var(--ease-out) both;
}
.drawer__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  background: var(--bg-elev);
  border-bottom: 1px solid var(--border);
}
.drawer__title {
  font-size: 15px;
  font-weight: 650;
  color: var(--fg);
}
.drawer__summary {
  margin-top: 3px;
  color: var(--fg-faint);
  font-size: 11px;
}
.drawer__actions {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}
.drawer__body {
  overflow-y: auto;
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.shortcuts-cheatsheet {
  --drawer-width: 680px;
}

.shortcuts-cheatsheet__body {
  gap: 16px;
}

.shortcuts-cheatsheet__section {
  min-width: 0;
}

.shortcuts-cheatsheet__section h3 {
