  align-items: center;
  justify-content: center;
  gap: 4px;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  font: inherit;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0;
  line-height: 1;
  white-space: nowrap;
}

.shortcut-combo__part,
.shortcut-combo__separator {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  min-width: 0.72em;
  line-height: 1;
}

.shortcut-combo__separator {
  min-width: auto;
  color: var(--fg-dim);
}

.shortcuts-cheatsheet__row kbd {
  justify-self: start;
  max-width: 100%;
  padding: 4px 7px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg);
  color: var(--fg);
  font: 650 11px/1.2 var(--mono);
  white-space: nowrap;
}

.shortcuts-cheatsheet__row div {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.shortcuts-cheatsheet__row strong {
  color: var(--fg);
  font-size: var(--font-control-small);
  line-height: 1.3;
}

.shortcuts-cheatsheet__desc {
  color: var(--fg-dim);
  font-size: var(--text-2xs);
  line-height: 1.4;
}

.skip-to-composer {
  position: fixed;
  top: 10px;
  left: 50%;
  z-index: var(--z-modal);
  transform: translate(-50%, -160%);
  padding: 7px 11px;
  border: 1px solid var(--accent);
  border-radius: 7px;
  background: var(--bg-elev);
  color: var(--accent);
  font-size: var(--font-control-small);
  font-weight: 650;
  text-decoration: none;
  box-shadow: none;
}

.skip-to-composer:focus-visible {
  transform: translate(-50%, 0);
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.24);
}

:where(button, a, input, textarea, select):focus-visible {
  outline-color: var(--accent);
}

@media (max-width: 760px) {
  .shortcuts-settings__row,
  .shortcuts-cheatsheet__row {
    grid-template-columns: minmax(0, 1fr);
  }

  .shortcuts-settings__control {
    justify-content: flex-start;
    flex-wrap: wrap;
  }

  .shortcuts-cheatsheet__row kbd {
    justify-self: start;
  }
}
