  grid-template-columns: repeat(2, minmax(0, 1fr)) 152px;
  align-items: end;
  gap: 8px;
  margin: 8px 0 0 33px;
}
.subagents-builtin-overrides__field {
  display: grid;
  min-width: 0;
  gap: 4px;
}
.subagents-builtin-overrides__field-label {
  color: var(--fg-faint);
  font-size: 10.5px;
  font-weight: 650;
  line-height: 1.3;
}
.subagents-builtin-overrides__field .settings-model-picker,
.subagents-builtin-overrides__field .mem-select {
  width: 100%;
}
.subagents-builtin-overrides__status {
  min-height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
}
.subagents-reset-override {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  white-space: nowrap;
}
.subagents-reset-override__state {
  color: var(--accent-strong);
  font-size: 10px;
  font-weight: 700;
}
.subagents-row-actions {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.subagents-invocation {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin: 8px 0 0 33px;
  padding: 6px 8px;
  border: 1px solid var(--border-soft);
  border-radius: 7px;
  background: color-mix(in srgb, var(--bg-elev) 48%, transparent);
}
.subagents-invocation__command {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  color: var(--fg-faint);
  font-size: 10.5px;
  line-height: 1.35;
}
.subagents-invocation__command code {
  overflow: hidden;
  color: var(--fg-dim);
  font-family: var(--mono);
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.subagents-invocation__copy {
  flex: 0 0 auto;
  min-height: 24px;
  background: transparent;
}
.subagents-invocation__copy .copybtn__label-inline {
  max-width: 80px;
}
.subagents-tryit-row {
  display: flex;
  align-items: center;
  gap: 8px;
}
.subagents-tryit-row .mem-input {
  flex: 1 1 auto;
}
.subagents-tryit-result {
  margin: 0;
  padding: 10px 12px;
  border: 1px solid var(--border-soft);
  border-radius: 8px;
  background: color-mix(in srgb, var(--bg-soft) 76%, transparent);
  color: var(--fg-dim);
  font-family: var(--mono);
  font-size: 12px;
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
  max-height: 260px;
  overflow-y: auto;
}
@media (max-width: 760px) {
  .subagents-toolbar {
    grid-template-columns: 1fr 1fr;
  }
  .subagents-toolbar .mem-input {
    grid-column: 1 / -1;
  }
  .subagents-builtin-overrides {
    grid-template-columns: 1fr;
  }
  .subagents-invocation {
    align-items: stretch;
    flex-direction: column;
  }
  .subagents-invocation > .btn {
    align-self: flex-start;
  }
  .subagents-builtin-overrides__status {
    min-height: 0;
    justify-content: flex-start;
  }
  .subagents-tool-scope-row {
    align-items: stretch;
    flex-direction: column;
    gap: 5px;
  }
  .subagents-tool-scope-row .mem-select {
    flex-basis: auto;
    width: 100%;
  }
}
.cap-dot {
  flex-shrink: 0;
  width: 7px;
  height: 7px;
  margin-top: 6px;
  border-radius: 999px;
  background: var(--fg-faint);
}
.cap-dot--connected {
  background: var(--ok);
}
.cap-dot--deferred {
  background: var(--ok);
  opacity: 0.78;
}
.cap-dot--initializing {
  background: var(--accent);
}
.cap-dot--failed {
  background: var(--err);
}
.cap-slash {
  flex-shrink: 0;
  width: 7px;
  font-family: var(--mono);
  color: var(--fg-faint);
  margin-top: 1px;
}
.cap-row__text {
  min-width: 0;
  flex: 1;
}
.cap-row__head {
  display: flex;
  align-items: center;
  gap: 7px;
}
.cap-row__name {
  font-size: 13px;
  font-weight: 500;
}
.cap-row__transport {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--fg-faint);
}
.cap-row__sub {
  font-size: 12px;
  color: var(--fg-dim);
  word-break: break-word;
}
.cap-row__actions {
  margin-left: auto;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 6px;
}
.cap-row__pending {
  font-size: 11px;
  font-weight: 650;
  color: var(--fg-faint);
}
.cap-row__builtin {
  flex-shrink: 0;
  padding: 1px 6px;
  border: 1px solid color-mix(in srgb, var(--accent) 22%, var(--border));
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 6%, var(--bg-soft));
  color: color-mix(in srgb, var(--accent) 70%, var(--fg-dim));
  font-size: 10px;
  font-weight: 550;
  letter-spacing: 0;
  line-height: 1.35;
}
.cap-row__update {
  border-color: color-mix(in srgb, var(--warn) 32%, var(--border));
  background: color-mix(in srgb, var(--warn) 9%, var(--bg-soft));
  color: color-mix(in srgb, var(--warn) 80%, var(--fg-dim));
}
.cap-row__update--activated {
  border-color: color-mix(in srgb, var(--ok) 30%, var(--border));
  background: color-mix(in srgb, var(--ok) 8%, var(--bg-soft));
  color: color-mix(in srgb, var(--ok) 72%, var(--fg-dim));
}
.cap-row__update--error {
  border-color: color-mix(in srgb, var(--err) 30%, var(--border));
  background: color-mix(in srgb, var(--err) 8%, var(--bg-soft));
  color: color-mix(in srgb, var(--err) 76%, var(--fg-dim));
}
.cap-row--skill {
  align-items: center;
}
.cap-switch {
  --wails-draggable: no-drag;
  display: inline-flex;
}
.cap-switch input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}
.cap-switch__track {
  position: relative;
  width: 30px;
  height: 17px;
  border-radius: 999px;
  background: var(--border);
  transition: background 0.14s;
}
.cap-switch__track::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: var(--bg-elev);
  transition: transform 0.14s;
}
.cap-switch input:checked + .cap-switch__track {
  background: var(--ok);
}
.cap-switch input:checked + .cap-switch__track::after {
  transform: translateX(13px);
}
.cap-switch input:disabled + .cap-switch__track {
  opacity: 0.5;
}
/* ── management modals: shared shell for settings, history, and trash ───────── */
.management-modal-backdrop {
  --wails-draggable: no-drag;
  position: fixed;
  inset: 0;
  z-index: var(--z-modal);
  background: rgba(0, 0, 0, 0.48);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  overflow: hidden;
  animation: backdrop-in var(--dur-base) var(--ease-out) both;
}

.topicbar__worktree-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  border: 0;
  padding: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
}
.topicbar__worktree-btn span {
  font-size: 11px;
  opacity: 0.9;
  text-decoration: underline dotted;
}
.topicbar__worktree-btn:focus-visible {
  border-radius: 3px;
  outline: none;
  box-shadow: var(--focus-ring);
}

.management-modal {
  display: flex;
  flex-direction: column;
  width: min(1360px, calc(100vw - 96px));
  height: min(900px, calc(100vh - 80px));
  background: var(--bg-soft);
  border: 1px solid var(--border);
  border-radius: 14px;
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.32);
  overflow: hidden;
  transform-origin: 50% 48%;
  /* No will-change / fill-mode: anything that keeps a transform applied after
     entry pins a compositor layer rasterized at the entrance scale, leaving
     text blurry on Windows fractional DPI until the next repaint (#3838). */
  animation: modal-in 280ms var(--ease-out);
}
.history-modal {
  width: min(1360px, calc(100vw - 96px));
}

.management-modal__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 20px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-elev);
  flex: 0 0 auto;
}

.management-modal__title {
  font-size: var(--text-base);
  font-weight: 700;
  color: var(--fg);
}

.management-modal__summary {
  margin-top: 3px;
  color: var(--fg-faint);
  font-size: var(--text-xs);
}

.management-modal__actions {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.recovery-lineage-dialog {
  width: min(680px, calc(100vw - 48px));
  height: auto;
  max-height: min(720px, calc(100vh - 64px));
}
.recovery-lineage-dialog .management-modal__title {
  display: flex;
  align-items: center;
  gap: 7px;
}
.recovery-lineage-dialog__body {
  min-height: 120px;
  overflow: auto;
  padding: 12px 18px;
}
.recovery-lineage-dialog__member {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 18px;
  padding: 14px 2px;
  border-bottom: 1px solid var(--border);
}
.recovery-lineage-dialog__member-copy {
  min-width: 0;
}
.recovery-lineage-dialog__member-name {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--fg);
  font-size: var(--text-sm);
  font-weight: 650;
}
.recovery-lineage-dialog__member-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 6px;
  color: var(--fg-faint);
  font-size: var(--text-xs);
}
.recovery-lineage-dialog__preview {
  margin-top: 7px;
  color: var(--fg-dim);
  font-size: var(--text-sm);
  line-height: 1.45;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.recovery-lineage-dialog__version-note {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-top: 5px;
  border: 0;
  padding: 0;
  background: transparent;
  color: var(--fg-faint);
  cursor: pointer;
  font-size: var(--text-xs);
}
.recovery-lineage-dialog__version-note:hover { color: var(--fg); }
.recovery-lineage-dialog__version-note:disabled { opacity: 0.5; cursor: default; }
.recovery-lineage-dialog__note-editor {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 7px;
}
.recovery-lineage-dialog__note-editor input {
  min-width: 0;
  flex: 1 1 220px;
  height: 30px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--bg-soft);
  color: var(--fg);
  padding: 0 9px;
}
.recovery-lineage-dialog__member-actions {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 7px;
}
.recovery-lineage-dialog__actions {
  padding: 12px 18px;
  border-top: 1px solid var(--border);
}
@keyframes modal-in {
  0% {
    transform: translate3d(0, 10px, 0) scale(0.982);
    opacity: 0;
  }
  64% {
    transform: translate3d(0, -1px, 0) scale(1.002);
    opacity: 1;
  }
  100% {
    transform: none;
    opacity: 1;
  }
}
@keyframes modal-out {
  to {
    transform: translate3d(0, 8px, 0) scale(0.985);
    opacity: 0;
  }
}
/* Exit animations for modals/backdrops driven by useDeferredClose. */
.management-modal[data-state="closing"],
.settings-modal[data-state="closing"] {
  animation: modal-out var(--dur-base) var(--ease-out) both;
}
.management-modal-backdrop[data-state="closing"],
.settings-modal-backdrop[data-state="closing"] {
  animation: backdrop-out var(--dur-base) var(--ease-out) both;
}

/* ── history manager: searchable list with preview and actions ─────────────── */
.history-manager {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  overflow: hidden;
}
.history-toolbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-soft);
}
.history-content {
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 0.38fr) minmax(0, 0.62fr);
  overflow: hidden;
}
.history-list {
  min-width: 0;
  overflow-y: auto;
  padding: 14px 14px 16px;
  border-right: 1px solid var(--border);
}
.history-list--trash {
  min-height: 0;
}
.history-search {
  flex: 1 1 360px;
  max-width: 520px;
  margin: 0;
}
/* H5: segmented pill filters replace the native selects. */
.history-filter {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  flex: 0 0 auto;
  padding: 3px;
  border-radius: 999px;
  background: var(--bg);
  border: 1px solid var(--border);
}
.history-filter__pill {
  --wails-draggable: no-drag;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 26px;
  padding: 0 11px;
  border: none;
  border-radius: 999px;
  background: transparent;
  color: var(--fg-dim);
  font: inherit;
  font-size: var(--font-control-small);
  font-weight: 550;
  white-space: nowrap;
  transition: background 0.12s, color 0.12s;
}
.history-filter__pill:hover:not(:disabled) {
  color: var(--fg);
}
.history-filter__pill--on {
  background: var(--accent-soft);
  color: var(--accent);
}
.history-filter__pill:disabled {
  opacity: 0.4;
  cursor: default;
}
.history-filter__count {
  font-size: 10px;
  font-variant-numeric: tabular-nums;
  color: var(--fg-faint);
}
.history-filter__pill--on .history-filter__count {
  color: var(--accent);
}
.history-clear {
  height: 30px;
  padding: 0 10px;
  color: var(--fg-dim);
}
.history-clear:hover {
  color: var(--fg);
}
.history-clear--confirm {
  color: #ff8b6d;
  border-color: rgba(255, 139, 109, 0.45);
  background: rgba(255, 139, 109, 0.1);
}
.history-clear--confirm:hover {
  color: #ff9f86;
  border-color: rgba(255, 139, 109, 0.62);
  background: rgba(255, 139, 109, 0.16);
}
.history-preview {
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  background: var(--bg);
}
.history-preview--empty {
  align-items: center;
  justify-content: center;
}
.history-preview__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--border-soft);
  background: var(--bg-soft);
}
.history-preview__copy {
  flex: 1 1 auto;
  min-width: 0;
}
.history-preview__title {
  overflow: hidden;
  color: var(--fg);
  font-size: var(--font-control);
  font-weight: 650;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.history-preview__meta {
  margin-top: 3px;
  color: var(--fg-faint);
  font-size: var(--font-caption);
}
.history-preview__actions {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: nowrap;
  gap: 8px;
}
.history-preview__actions .btn {
  white-space: nowrap;
}
.history-preview__body {
  flex: 1;
  min-height: 0;
  overflow: hidden;
}
.history-preview--empty {
  display: grid;
  place-items: center;
}
.history-preview__empty {
  color: var(--fg-faint);
  font-size: var(--font-control);
}
.history-preview__body .transcript {
  --transcript-inline-pad: 14px;
  padding: 14px 0 18px;
}
.history-preview__body .transcript > * {
  max-width: none;
}
.hist-item {
  position: relative;
  display: flex;
  align-items: stretch;
  gap: 4px;
  margin-bottom: 6px;
  background: var(--bg-soft);
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
  transition: border-color 0.12s, transform 0.12s cubic-bezier(0.34, 1.4, 0.5, 1), box-shadow 0.12s;
}
.hist-item:hover {
  border-color: var(--fg-faint);
  transform: translateX(2px);
}
.hist-item--current {
  border-color: var(--accent-soft);
}
/* H1: selection shows a 3px accent bar + soft tint instead of a full ring. */
.hist-item--selected {
  border-color: var(--accent-soft);
  background: var(--accent-soft);
  box-shadow: none;
}
.hist-item--selected::before {
  content: "";
  position: absolute;
  left: 0;
  top: 7px;
  bottom: 7px;
  width: 3px;
  border-radius: 0 3px 3px 0;
  background: var(--accent);
}
.hist-item__main {
  --wails-draggable: no-drag;
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
  text-align: left;
  padding: 9px 10px;
  background: transparent;
  border: none;
  color: var(--fg);
  font: inherit;
}
.hist-item__preview {
  font-size: 13px;
  line-height: 1.35;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hist-item__meta {
  display: flex;
  align-items: center;
  flex-wrap: nowrap;
  gap: 6px;
  min-width: 0;
  font-size: 11px;
  color: var(--fg-faint);
}
.hist-item__metaspacer {
  flex: 1 1 auto;
  min-width: 4px;
}
.hist-item__stat {
  flex: none;
  white-space: nowrap;
}
.hist-item__dot {
  flex: none;
  opacity: 0.5;
}
.hist-item__scope {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--fg-dim);
}
/* H2: status badges become a small color dot + label. */
.hist-item__badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  flex: none;
  color: var(--fg-dim);
  font-size: 10.5px;
  letter-spacing: 0.01em;
  white-space: nowrap;
}
.hist-item__badge::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--fg-faint);
}
.hist-item__badge--current { color: var(--accent); }
.hist-item__badge--current::before { background: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.hist-item__badge--open::before { background: #3b82f6; }
.hist-item__badge--deleted::before { background: var(--fg-faint); }
.hist-item__rename {
  flex: 1;
  min-width: 0;
  margin: 6px;
  padding: 6px 8px;
  background: var(--bg);
  border: 1px solid var(--accent-soft);
  border-radius: 6px;
  color: var(--fg);
  font: inherit;
  font-size: 13px;
}
@media (max-width: 760px) {
  .management-modal-backdrop {
    align-items: stretch;
    padding: 12px;
  }
  .management-modal,
  .history-modal {
    width: calc(100vw - 24px);
    max-height: calc(100vh - 24px);
  }
  .management-modal__head,
  .history-toolbar,
  .history-preview__head {
    flex-wrap: wrap;
  }
  .history-preview__actions {
    flex-wrap: wrap;
    max-width: 100%;
  }
  .history-content {
    grid-template-columns: minmax(0, 1fr);
  }
  .history-list {
    max-height: 40vh;
  }
  .history-preview {
    min-height: 260px;
  }
}

/* ── settings centre modal ──────────────────────────────────────────────────── */
.settings-modal-backdrop {
  --wails-draggable: no-drag;
  padding: clamp(0px, calc((900px - 100vw) * 0.114), 16px);
}

.settings-modal {
  width: min(1360px, calc(100vw - clamp(32px, calc(96px - (900px - 100vw) * 0.457), 96px)));
}

/* ── settings centre layout ─────────────────────────────────────────────────── */
.settings-center {
  display: grid;
  grid-template-columns: clamp(180px, calc(248px - (900px - 100vw) * 0.486), 248px) minmax(0, 1fr);
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

.settings-center__nav {
  border-right: 1px solid var(--border);
  background: var(--bg-soft);
  padding: 10px;
}

.settings-center__navitem {
  --wails-draggable: no-drag;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 2px;
  width: 100%;
  min-width: 0;
  padding: 9px 10px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--fg-dim);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.settings-center__navitem:hover {
  background: var(--sidebar-hover);
  color: var(--fg);
}

.settings-center__navitem--active {
  background: var(--bg-elev-2);
  color: var(--fg);
  box-shadow: inset 0 0 0 1px var(--border), 0 8px 18px rgba(0, 0, 0, 0.14);
}

.settings-center__navitem--active::before {
  content: "";
  position: absolute;
