}

.settings-page__header {
  margin-bottom: 18px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--border-soft);
}

.settings-page__title {
  font-size: var(--text-xl);
  font-weight: 700;
  color: var(--fg);
  margin: 0 0 4px 0;
}

.settings-page__desc {
  font-size: var(--font-control-small);
  color: var(--fg-dim);
  margin: 0;
  line-height: 1.45;
}

/* ── settings design system ─────────────────────────────────────────────────── */
.settings-section,
.settings-page--manager .mem-section {
  min-width: 0;
  margin-bottom: 16px;
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: color-mix(in srgb, var(--bg-elev-2) 76%, var(--bg-elev));
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.08);
}

.settings-section__head,
.settings-page--manager .mem-section__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 12px;
}

.settings-section__head > div:first-child,
.settings-page--manager .mem-section__head > div:first-child {
