}

.settings-section__title,
.settings-page--manager .mem-section__title {
  font-size: var(--font-control);
  font-weight: 700;
  color: var(--fg);
}

.settings-section__desc {
  margin-top: 4px;
  color: var(--fg-dim);
  font-size: var(--font-caption);
  line-height: 1.45;
}

.settings-section__actions,
.settings-page--manager .mem-section__actions {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  flex: 0 0 auto;
  margin: 0;
}

.settings-section__body {
  display: flex;
  flex-direction: column;
}

.settings-field {
