  line-height: 1.45;
}

.updates-control__hint {
  padding: 0 0 12px;
}

.updates-control__controls {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  min-width: 0;
}

.updates-control__action {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-width: 0;
  padding: 12px 0;
  border-top: 1px solid var(--border-soft);
}

.updates-control__action-copy {
  min-width: 0;
}

.updates-control__spinner {
