}

.settings-field__copy {
  min-width: 0;
}

.settings-field__label {
  color: var(--fg);
  font-size: var(--font-control-small);
  font-weight: 650;
  line-height: 1.35;
}

.settings-field__hint {
  margin-top: 4px;
  color: var(--fg-dim);
  font-size: var(--text-2xs);
  line-height: 1.45;
}

.settings-field__hint-tooltip {
  max-width: 100%;
}

.settings-field__hint-line {
