  flex-direction: column;
  min-width: 0;
}

.shortcuts-settings__conflict {
  margin-bottom: 10px;
  padding: 8px 10px;
  border: 1px solid color-mix(in srgb, var(--warn) 45%, var(--border));
  border-radius: 7px;
