  color: var(--warn);
  font-size: var(--font-control-small);
  line-height: 1.4;
}

.shortcuts-settings__row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(220px, max-content);
  gap: 18px;
  align-items: center;
  min-width: 0;
  padding: 12px 0;
  border-top: 1px solid var(--border-soft);
}

.shortcuts-settings__row:first-child {
  border-top: none;
}

.shortcuts-settings__copy {
  min-width: 0;
}

.shortcuts-settings__label {
  color: var(--fg);
  font-size: var(--font-control-small);
  font-weight: 650;
  line-height: 1.35;
}

.shortcuts-settings__desc {
  margin-top: 3px;
  color: var(--fg-dim);
  font-size: var(--text-2xs);
  line-height: 1.4;
}

.shortcuts-settings__control {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  min-width: 0;
}

.shortcuts-settings__key {
  --wails-draggable: no-drag;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 104px;
  height: 30px;
  padding: 0 10px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--bg);
  color: var(--fg);
  font: 650 12px/1 var(--mono);
  overflow: hidden;
  white-space: nowrap;
  cursor: pointer;
}

.shortcuts-settings__key:hover {
  border-color: var(--accent-soft);
  color: var(--accent);
}

.shortcuts-settings__key:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.shortcuts-settings__key--recording {
  border-color: var(--accent);
  background: var(--accent-soft);
  color: var(--accent);
}

.status-bar-items-editor {
  display: grid;
  gap: 8px;
  width: 100%;
  max-width: 520px;
  margin-left: auto;
}

.status-bar-items-editor__summary {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  min-height: 32px;
}

.status-bar-items-editor__summary-text {
  min-width: 0;
  overflow: hidden;
  color: var(--fg-dim);
  font-size: var(--font-control-small);
  font-weight: 600;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.status-bar-items-editor__toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 28px;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--bg-elev);
  color: var(--fg-dim);
}

.status-bar-items-editor__toggle:hover:not(:disabled),
.status-bar-items-editor__toggle:focus-visible:not(:disabled) {
  outline: none;
  border-color: color-mix(in srgb, var(--fg-faint) 34%, var(--border));
  background: var(--bg-elev-2);
  color: var(--fg);
}

.status-bar-items-editor__list {
  display: grid;
  gap: 6px;
}

.status-bar-item-row {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  min-height: 36px;
  padding: 5px 6px 5px 9px;
  border: 1px solid var(--border-soft);
  border-radius: 8px;
  background: var(--bg-elev);
  transition: background var(--dur-fast), border-color var(--dur-fast), box-shadow var(--dur-fast), opacity var(--dur-fast), transform var(--dur-fast);
}

.status-bar-item-row--hidden {
  color: var(--fg-faint);
  background: color-mix(in srgb, var(--bg-elev) 70%, transparent);
}

.status-bar-item-row--dragging {
  opacity: 0.56;
  transform: scale(0.992);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 20%, transparent);
}

.status-bar-item-row--drag-over {
  border-color: color-mix(in srgb, var(--accent) 42%, var(--border));
  background: color-mix(in srgb, var(--accent) 8%, var(--bg-elev));
}

.status-bar-item-row--drop-before::before,
.status-bar-item-row--drop-after::after {
  content: "";
  position: absolute;
  left: 28px;
  right: 14px;
  z-index: var(--z-local-raised);
  height: 2px;
  border-radius: 999px;
  background: var(--accent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 22%, transparent), 0 3px 8px color-mix(in srgb, var(--accent) 24%, transparent);
  pointer-events: none;
}

.status-bar-item-row--drop-before::before {
  top: -5px;
}

.status-bar-item-row--drop-after::after {
  bottom: -5px;
}

.status-bar-item-row__drag {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 24px;
  flex: 0 0 22px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--fg-faint);
  cursor: grab;
  touch-action: none;
  user-select: none;
}

.status-bar-item-row__drag:hover,
.status-bar-item-row__drag:focus-visible {
  outline: none;
  background: var(--bg-elev-2);
  color: var(--fg-dim);
}

.status-bar-item-row__drag:active {
  cursor: grabbing;
}

.status-bar-item-row__drag:disabled {
  cursor: not-allowed;
  opacity: 0.42;
}

.status-bar-item-row > .tooltip-trigger {
  display: inline-flex;
  align-items: center;
}

.status-bar-item-row__toggle {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-width: 0;
  gap: 8px;
  cursor: pointer;
}

.status-bar-item-row__toggle input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  opacity: 0;
  pointer-events: none;
}

.status-bar-item-row__check {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  flex: 0 0 16px;
  border: 1px solid var(--border);
  border-radius: 5px;
  background: var(--bg);
  color: var(--accent);
}

.status-bar-item-row__toggle:has(input:focus-visible) .status-bar-item-row__check {
  box-shadow: 0 0 0 3px var(--accent-soft);
}

.status-bar-item-row__toggle:has(input:disabled) {
  cursor: not-allowed;
}

.status-bar-item-row__label {
  min-width: 0;
  overflow: hidden;
  color: var(--fg);
  font-size: var(--font-control-small);
  font-weight: 600;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.status-bar-item-row--hidden .status-bar-item-row__label {
  color: var(--fg-faint);
  font-weight: 550;
}

.status-bar-item-row__actions {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.status-bar-item-row__order {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 24px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  color: var(--fg-dim);
}

.status-bar-item-row__order:hover:not(:disabled),
.status-bar-item-row__order:focus-visible:not(:disabled) {
  outline: none;
  border-color: var(--border);
  background: var(--bg-elev-2);
  color: var(--fg);
}

.status-bar-item-row__order:disabled {
  color: color-mix(in srgb, var(--fg-faint) 62%, transparent);
  cursor: not-allowed;
}

.settings-sound-editor {
