/* ── responsive: compact content on narrow screens ─────────────────────────── */
@media (max-width: 900px) {
  .settings-modal {
    height: min(900px, calc(100vh - 32px));
  }

  .settings-center__content {
    padding: 18px 20px;
  }

  .settings-page--form,
  .settings-page--manager {
    max-width: none;
  }

  .settings-section,
  .settings-page--manager .mem-section {
    padding: 14px;
  }

  .settings-section__head {
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
  }

  .settings-field {
    grid-template-columns: 1fr;
    gap: 8px;
    align-items: stretch;
  }

  .settings-field__control,
  .settings-inline-controls {
    justify-content: flex-start;
  }

  .settings-inline-controls {
    flex-wrap: wrap;
  }

  .settings-inline-controls .set-seg {
    max-width: 100%;
    min-width: 0;
    overflow-x: auto;
  }

  .settings-inline-controls .set-seg__btn {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .settings-subtabs {
    display: inline-flex;
    max-width: 100%;
    flex-wrap: wrap;
  }

  .memory-tabs-row {
    align-items: center;
    flex-direction: row;
    flex-wrap: wrap;
    gap: 10px 12px;
  }

  .memory-tabs-row__tail {
    display: flex;
    align-items: center;
    gap: 12px;
    min-width: 0;
    flex: 0 1 100%;
  }

  .memory-tabs-row__spacer {
    display: none;
  }

  .memory-suggestion-tab {
    margin-left: 0;
  }

  .mem-ws-select {
    flex: 1 1 auto;
    min-width: 0;
  }

  .mem-ws-select__label {
    max-width: none;
    white-space: normal;
    overflow-wrap: anywhere;
  }

  .settings-subtab {
    flex: 0 0 auto;
  }

  .settings-page--manager .mem-add {
    grid-template-columns: 1fr;
  }

  .provider-models-row,
  .set-key {
    grid-template-columns: 1fr;
    display: grid;
  }
}

@media (max-width: 760px) {
  .settings-modal-backdrop {
    padding: 0;
  }

  .settings-modal {
    width: 100vw;
    height: 100vh;
    border-radius: 0;
  }

