.settings-config-path {
  margin-top: 18px;
}

@media (max-width: 1180px) {
  .settings-page--bots .bot-connection-table {
    gap: 8px;
    overflow: visible;
    border: 0;
    background: transparent;
  }

  .settings-page--bots .bot-connection-table__header {
    display: none;
  }

  .settings-page--bots .bot-connection-row {
    border: 1px solid var(--border);
    border-radius: 8px;
    background: var(--bg-elev);
  }

  .settings-page--bots .bot-connection-row:last-child {
    border-bottom: 1px solid var(--border);
  }

  .settings-page--bots .bot-connection-row__grid {
    grid-template-columns: minmax(72px, 0.52fr) minmax(180px, 1fr) max-content;
    grid-template-areas:
      "channel identity state"
      "channel identity actions";
    align-items: center;
    gap: 8px 12px;
    min-height: 0;
    padding: 12px 14px;
  }

  .settings-page--bots .bot-connection-row__channel {
    grid-area: channel;
  }

  .settings-page--bots .bot-connection-row__identity-cell {
    grid-area: identity;
  }

  .settings-page--bots .bot-connection-row__state {
    grid-area: state;
  }

  .settings-page--bots .bot-connection-row__actions {
    grid-area: actions;
  }

  .settings-page--bots .bot-connection-row__state,
  .settings-page--bots .bot-connection-row__actions {
    justify-content: flex-end;
    flex-wrap: wrap;
    width: auto;
  }

  .settings-page--bots .bot-connection-row__channel,
  .settings-page--bots .bot-connection-row__identity-cell {
    align-self: center;
  }

  .settings-page--bots .bot-connection-row__actions .btn {
    max-width: 100%;
  }

  .settings-page--bots .bot-manual-form .bot-card-field > div {
    justify-content: flex-start;
  }

  .settings-page--bots .bot-manual-form .bot-card-field .set-seg {
    width: fit-content;
    max-width: 100%;
  }

  .settings-page--bots .bot-manual-form .bot-card-field .set-seg__btn {
    flex: 0 1 auto;
    min-width: 76px;
  }
}

/* QR 扫码面板：在 1080px 提前切换单列，防止右侧文字/按钮溢出容器 */
@media (max-width: 1080px) {
  .bot-connect-panel,
  .bot-connect-panel--phone {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 980px) {
  .settings-center {
    grid-template-columns: minmax(176px, 220px) minmax(0, 1fr);
  }

  .settings-center__content {
    padding: 20px 24px;
  }

  .settings-section,
  .settings-page--manager .mem-section {
    padding: 14px;
  }

  .settings-field,
  .settings-field--wide-copy,
  .bot-access-panel .settings-field,
  .bot-detail-card .settings-field,
  .bot-advanced__body .settings-field {
    grid-template-columns: minmax(0, 1fr);
    gap: 8px;
    align-items: start;
  }

  /* 危险操作区块在中等宽度下改为纵向堆叠，避免两列 grid 压缩导致
     右侧按钮被 .settings-center__content 的 overflow-x: hidden 裁切。 */
  .bot-detail-section--danger {
    grid-template-columns: minmax(0, 1fr);
    align-items: start;
  }
  .bot-detail-section--danger .inline-confirm {
    justify-content: flex-start;
  }

  .settings-field__control,
  .settings-inline-controls {
    justify-content: flex-start;
    width: 100%;
    max-width: 100%;
  }

  .settings-field__control > .mem-input,
  .settings-field__control > .mem-select,
  .settings-field__control > .model-picker,
  .settings-field__control > .settings-model-picker {
    width: 100%;
    max-width: 100%;
  }

  .settings-inline-controls,
  .provider-access-card__head,
  .provider-access-card__actions,
  .set-rules__add {
    flex-wrap: wrap;
  }

  .bot-simple-hero {
    flex-direction: column;
  }

  .bot-overview-grid,
  .bot-channel-manager {
    grid-template-columns: 1fr;
  }

  .bot-channel-tabs {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .bot-channel-tab {
    min-height: 64px;
  }

  .bot-channel-tab__text small {
    display: none;
  }

  .bot-mobile-remote--overview .bot-mobile-remote__qr {
    min-height: 220px;
  }

  .bot-mobile-remote__advanced {
    grid-template-columns: 1fr;
  }

  .bot-channel-manager-card__head,
  .bot-channel-setup-card__head {
    flex-direction: column;
  }

  .bot-choice-grid,
  .bot-step-chips,
