/* ── tool card extras: nested sub-agent, multi-edit labels ───── */
.tool__difflabel {
  font-family: var(--mono);
  font-size: var(--text-xs);
  color: var(--fg-faint);
  margin: 6px 0 2px;
}
.tool__body + .tool__body .tool__difflabel {
  margin-top: 2px;
}
/* sub-agent calls render indented under their parent task card — the base
/* sub-agent calls render indented under their parent task card — the base
   tool__body already provides border-left + 12px padding, so subagent just
   needs left indent for hierarchy.  Expanded padding is handled by
   .tool--open .tool__body. */
.tool--subagent .tool__body {
  padding-left: 24px;
}
.tool__nested {
  margin: 8px 0;
  padding-left: 16px;
}
.tool__nested .tool__nested {
  border-left: 2px solid var(--border);
  margin-left: 16px;
}

/* ── live task list, pinned above the composer ─────────────────────────────── */
.todobar {
  max-width: var(--maxw);
  margin: 0 auto 8px;
  border: 1px solid var(--border);
  border-radius: 9px;
  background: var(--bg-soft);
  overflow: hidden;
  animation: todobar-in var(--dur-base) var(--ease-out) both;
}
@keyframes todobar-in {
  from {
    opacity: 0;
    transform: translateY(var(--motion-rise));
  }
}
.todobar__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 6px;
  max-height: 220px;
  overflow-y: auto;
  animation: todo-list-in var(--dur-base) var(--ease-out) both;
}
@keyframes todo-list-in {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }
}
.todobar__item {
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: flex-start;
  gap: 10px;
  font-size: 13px;
  line-height: 1.5;
  padding-block: 2px;
}
.todobar__status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px 8px;
  border: 1px solid var(--border-soft);
  border-radius: 999px;
  background: var(--bg-soft);
  color: var(--fg-dim);
  font-size: 11px;
  line-height: 1.35;
  white-space: nowrap;
}
.todobar__status--completed {
  border-color: color-mix(in srgb, var(--ok) 30%, var(--border-soft));
  color: var(--ok);
}
.todobar__status--in_progress {
  border-color: color-mix(in srgb, var(--accent) 32%, var(--border-soft));
  color: var(--accent);
}
.todobar__status--waiting {
  border-color: color-mix(in srgb, var(--warn) 32%, var(--border-soft));
  color: var(--warn);
}
.todobar__status--paused {
  border-color: color-mix(in srgb, var(--fg-dim) 32%, var(--border-soft));
  color: var(--fg-dim);
}
.todobar__text {
  min-width: 0;
}
.todobar__item--completed .todobar__text {
  color: var(--fg-faint);
  text-decoration: line-through;
}
.todobar__item--in_progress .todobar__text {
  color: var(--fg);
  font-weight: 500;
}
.todobar__item--waiting .todobar__text,
.todobar__item--paused .todobar__text {
  color: var(--fg-dim);
  font-weight: 500;
}
.todobar__item--pending .todobar__text {
  color: var(--fg-dim);
}
.todobar__item--sub {
  padding-left: 18px;
}

.composer-guidance-shelf {
  --wails-draggable: no-drag;
  display: grid;
  gap: 5px;
  max-width: var(--maxw);
  margin: 0 auto 8px;
  padding: 0 4px;
}

.composer-guidance-head {
  display: flex;
  align-items: center;
  min-height: 22px;
  padding: 0 6px;
}

.composer-guidance-head__label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--fg-dim);
  font-size: 12px;
  font-weight: 620;
}

.composer-guidance-head__label > svg {
  color: var(--fg-faint);
}

.composer-guidance-list {
  display: grid;
  gap: 4px;
  padding: 5px;
  border: 1px solid var(--border-soft);
  border-radius: 9px;
  background: color-mix(in srgb, var(--bg-soft) 74%, transparent);
}

.composer-guidance-item {
  min-height: 32px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) repeat(3, auto);
  align-items: center;
  gap: 8px;
  padding: 5px 6px 5px 8px;
  border: 1px solid color-mix(in srgb, var(--accent) 18%, var(--border-soft));
  border-radius: 7px;
  background: color-mix(in srgb, var(--bg-elev) 78%, transparent);
  color: var(--fg-dim);
  box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 5%, transparent);
}

.composer-guidance-item__icon {
  flex: 0 0 auto;
  color: var(--fg-faint);
}

.composer-guidance-item__text {
  min-width: 0;
  color: var(--fg-dim);
  font-size: 13px;
  font-weight: 520;
  line-height: 1.35;
  overflow: hidden;
  overflow-wrap: anywhere;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.composer-guidance-item__editor {
  min-width: 0;
  width: 100%;
  height: 28px;
  border: 1px solid var(--border-soft);
  border-radius: 6px;
  background: var(--bg-elev);
  color: var(--fg);
  font: inherit;
  font-size: 13px;
  padding: 0 8px;
}

.composer-guidance-item__guide {
  min-width: 0;
  height: 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 0 8px;
  border: 1px solid color-mix(in srgb, var(--accent) 22%, var(--border-soft));
  border-radius: 6px;
  background: color-mix(in srgb, var(--accent) 8%, var(--bg-elev));
  color: var(--accent);
  font-size: 12px;
  font-weight: 650;
  line-height: 1;
  white-space: nowrap;
}

.composer-guidance-item__guide:not(:disabled):hover,
.composer-guidance-item__guide:not(:disabled):focus-visible {
  background: color-mix(in srgb, var(--accent) 13%, var(--bg-elev));
  border-color: color-mix(in srgb, var(--accent) 34%, var(--border-soft));
}

.composer-guidance-item__guide:disabled {
  opacity: 0.55;
  cursor: default;
}

.composer-guidance-item__action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--fg-faint);
}

.composer-guidance-item__action:not(:disabled):hover,
.composer-guidance-item__action:not(:disabled):focus-visible {
  background: color-mix(in srgb, var(--bg-elev-2) 80%, transparent);
  color: var(--fg);
}

.composer-guidance-item__action:disabled {
  opacity: 0.6;
  cursor: default;
}

.composer-guidance-more {
  min-height: 24px;
  display: flex;
  align-items: center;
  gap: 5px;
  justify-self: start;
  margin-left: 28px;
  padding: 2px 7px 3px;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  color: var(--fg-faint);
  font-size: 12px;
  font-family: inherit;
  line-height: 1.3;
}

.composer-guidance-more:not(:disabled):hover,
.composer-guidance-more:not(:disabled):focus-visible {
  border-color: var(--border-soft);
  background: color-mix(in srgb, var(--bg-elev-2) 72%, transparent);
  color: var(--fg-dim);
}

@media (max-width: 620px) {
  .composer-guidance-shelf {
    padding: 0;
  }

  .composer-guidance-item {
    padding-left: 7px;
  }
}

.composer-context {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 8px;
  margin-bottom: 8px;
  /* Many attachments (images/refs) stack rows without bound and squeeze the
     transcript viewport (see #7578). Cap the area and scroll internally. */
  max-height: min(30vh, 200px);
  overflow-y: auto;
}
.composer-context__item {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  position: relative;
  width: 196px;
  height: 64px;
  padding: 8px 30px 8px 8px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--panel);
  color: var(--fg-dim);
  font-size: 12.5px;
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--bg-elev) 70%, transparent);
}
.composer-context__item--image {
  width: 64px;
  padding: 4px;
  justify-content: center;
}
.composer-context__item--image-only {
  width: 76px;
  height: 76px;
}
.composer-context__item--workspace {
  border-color: color-mix(in srgb, var(--accent) 24%, var(--border));
  background: color-mix(in srgb, var(--accent) 7%, var(--panel));
}
.composer-context__label {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  width: 100%;
}
.composer-context__label > svg {
  flex-shrink: 0;
  color: var(--fg-faint);
}
.composer-context__item--workspace .composer-context__label > svg {
  color: var(--accent);
}
.composer-context__thumb {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 56px;
  height: 56px;
}
.composer-context__thumb--interactive {
  cursor: pointer;
  transition: transform 0.15s ease;
}
.composer-context__thumb--interactive:hover {
  transform: scale(1.08);
}
.composer-context__item--image-only .composer-context__thumb {
  width: 68px;
  height: 68px;
}
.composer-context__thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: var(--bg-soft);
}
.composer-context__fileicon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 38px;
  height: 38px;
  border-radius: 8px;
  color: var(--fg-dim);
  background: var(--bg-elev);
}
.composer-context__main {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.composer-context__name,
.composer-context__meta,
.composer-context__label span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.composer-context__name {
  color: var(--fg);
  font-weight: 560;
  line-height: 1.25;
}
.composer-context__meta {
  color: var(--fg-faint);
  font-size: 11px;
  line-height: 1.2;
}
.composer-context__remove-trigger,
.composer-context__item > .tooltip-trigger:last-child {
  position: absolute;
  top: 4px;
  right: 4px;
  z-index: var(--z-local-raised);
  line-height: 0;
}
.composer-context__item--image .composer-context__remove-trigger,
.composer-context__item--image > .tooltip-trigger:last-child {
  top: 2px;
  right: 2px;
}
.composer-context__item--image-only .composer-context__remove-trigger,
.composer-context__item--image-only > .tooltip-trigger:last-child {
  top: 3px;
  right: 3px;
}
.composer-context__remove,
.composer-context__item > .tooltip-trigger:last-child button {
  --wails-draggable: no-drag;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: color-mix(in srgb, #000 78%, transparent);
  color: #fff;
}
.composer-context__remove:hover,
.composer-context__item > .tooltip-trigger:last-child button:hover {
  color: #fff;
  background: color-mix(in srgb, #000 88%, transparent);
}
.composer-context__item--session {
  border-color: color-mix(in srgb, var(--accent) 24%, var(--border));
  background: color-mix(in srgb, var(--accent) 7%, var(--panel));
}
.composer-context__item--session .composer-context__label > svg {
  color: var(--accent);
}
.composer-context__item--selection {
  width: min(240px, 100%);
  border-color: color-mix(in srgb, var(--accent) 28%, var(--border));
  background: color-mix(in srgb, var(--accent) 8%, var(--panel));
  animation: composer-selection-in var(--dur-base) var(--ease-out) both;
}
.composer-context__item--selection .composer-context__fileicon {
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 11%, var(--bg-elev));
}
@keyframes composer-selection-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
}
@media (prefers-reduced-motion: reduce) {
  .composer-context__item--selection {
    animation: none;
  }
}
.slashmenu__item--special {
  border-bottom: 1px solid var(--border);
  background: color-mix(in srgb, var(--accent) 5%, var(--panel));
}
.slashmenu__item--special:hover {
  background: color-mix(in srgb, var(--accent) 10%, var(--panel));
}
.slashmenu__item--back {
  border-top: 1px solid var(--border);
  color: var(--fg-dim);
}
.slashmenu__item--back:hover {
  background: color-mix(in srgb, var(--fg) 6%, transparent);
}
.slashmenu__item--empty {
  color: var(--fg-faint);
  cursor: default;
}
.slashmenu__item--empty:hover {
  background: transparent;
}
.composer__pasted {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 8px;
  /* Pasting many long texts stacks fold blocks without bound and squeezes the
     transcript viewport (see #7578). Cap the list and scroll internally. */
  max-height: min(30vh, 240px);
  overflow-y: auto;
}
.composer__pasted-block {
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--panel);
  overflow: hidden;
  /* The capped .composer__pasted list is a column flex container; without
     this, flex-shrink would crush every block to a few px instead of
     scrolling (#7578). */
  flex-shrink: 0;
}
.composer__pasted-head {
  display: flex;
  align-items: center;
  gap: 7px;
  min-height: 34px;
  padding: 5px 6px 5px 9px;
  color: var(--fg-dim);
  font-size: 12.5px;
}
.composer__pasted-head > svg {
  flex-shrink: 0;
  color: var(--fg-faint);
}
.composer__pasted-label {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.composer__pasted-actions {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 4px;
}
.composer__pasted-head button {
  --wails-draggable: no-drag;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 24px;
  height: 24px;
  padding: 0 7px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--fg-faint);
  font: inherit;
  font-size: 12px;
}
.composer__pasted-head button:hover {
  color: var(--fg);
  background: color-mix(in srgb, var(--fg) 6%, transparent);
}
