/* onboarding — first-run gate covering the whole window. Sits above every
/* onboarding — first-run gate covering the whole window. Sits above every
   other layer; the card is centered, terminal-styled, with a faint scanline
   accent so it reads as "stop and paste a key" rather than a generic modal. */
.onboarding {
  position: fixed;
  inset: 0;
  z-index: var(--z-onboarding);
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(
      ellipse at top,
      rgba(217, 119, 87, 0.06) 0%,
      transparent 60%
    ),
    rgba(7, 8, 10, 0.92);
  backdrop-filter: none;
  --wails-draggable: drag;
}
.onboarding__card {
  --wails-draggable: no-drag;
  width: min(440px, calc(100vw - 48px));
  padding: 32px 32px 28px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 12px;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.55), 0 0 0 1px rgba(217, 119, 87, 0.04);
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.onboarding__logo {
  width: 36px;
  height: 36px;
  align-self: flex-start;
  margin-bottom: 4px;
}
.onboarding__title {
  font-size: 18px;
  font-weight: 600;
  letter-spacing: 0.2px;
  color: var(--fg);
}
.onboarding__tag {
  font-size: 13px;
  line-height: 1.55;
  color: var(--fg-dim);
  margin-bottom: 6px;
}
.onboarding__label {
  font-size: 12px;
  font-weight: 500;
  color: var(--fg-dim);
  text-transform: uppercase;
  letter-spacing: 0.6px;
}
.onboarding__input {
  font-family: var(--mono);
  font-size: 13px;
  padding: 10px 12px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 6px;
  color: var(--fg);
  outline: none;
  transition: border-color 120ms ease, box-shadow 120ms ease;
}
.onboarding__input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(217, 119, 87, 0.18);
}
.onboarding__input:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}
.onboarding__error {
  font-size: 12px;
  line-height: 1.5;
  color: #ff8b7a;
  background: rgba(255, 70, 70, 0.08);
  border: 1px solid rgba(255, 70, 70, 0.25);
  border-radius: 6px;
  padding: 8px 10px;
}
.onboarding__submit {
  margin-top: 4px;
  padding: 10px 14px;
  background: var(--accent);
  color: #1a0e08;
  border: none;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: background 120ms ease, transform 80ms ease;
}
.onboarding__submit:hover:not(:disabled) {
  background: #e08868;
}
.onboarding__submit:active:not(:disabled) {
  transform: translateY(1px);
}
.onboarding__submit:disabled {
  opacity: 0.7;
  cursor: not-allowed;
}
.onboarding__provider {
  padding: 9px 14px;
  background: var(--bg-soft);
  color: var(--fg);
  border: 1px solid var(--border);
  border-radius: 6px;
  font-size: 13px;
  font-weight: 550;
  font-family: inherit;
  transition: background 120ms ease, border-color 120ms ease;
}
.onboarding__provider:hover:not(:disabled) {
  background: var(--bg-hover, rgba(128, 128, 128, 0.08));
  border-color: var(--border-2, var(--border));
}
.onboarding__provider:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.onboarding__spinner {
  display: inline-block;
  width: 12px;
  height: 12px;
  border: 2px solid rgba(26, 14, 8, 0.3);
  border-top-color: #1a0e08;
  border-radius: 50%;
  animation: onboarding-spin 0.7s linear infinite;
}
@keyframes onboarding-spin {
  to { transform: rotate(360deg); }
}
.onboarding__links {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--fg-dim);
  margin-top: 4px;
}
.onboarding__link {
  background: none;
  border: none;
  padding: 0;
  color: var(--accent);
  font: inherit;
  text-decoration: underline;
  text-underline-offset: 2px;
}
.onboarding__link:hover {
  color: #e08868;
}
.onboarding__sep {
  opacity: 0.5;
}
.onboarding__privacy {
  opacity: 0.8;
}
.onboarding__skip {
  background: none;
  border: none;
  padding: 4px 0;
  margin-top: 2px;
  color: var(--fg-dim);
  font-size: 12px;
  font-family: inherit;
  text-align: center;
  transition: color 120ms ease;
}
.onboarding__skip:hover:not(:disabled) {
  color: var(--fg);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.onboarding__skip:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Memory filter input: a full-width mem-input variant that sits below
/* Memory filter input: a full-width mem-input variant that sits below
   the section title. The existing mem-input already has a 28px height
   and the right border tokens; this just sets margin so it doesn't
   crowd the doc list. */
.mem-filter {
  margin: 4px 0 8px;
  width: 100%;

}

/* InlineDiff: a compact before/after diff card. The header strip carries
/* InlineDiff: a compact before/after diff card. The header strip carries
   the filename, the +/- counts, and a Copy button. The body is a monospace
   pre with +/- row coloring. The CSS tokens are the same --add-bg /
   --del-bg the existing DiffView uses, so light/dark theme changes apply
   uniformly. */
.inline-diff {
  margin: 4px 0;
  border: 1px solid var(--border-soft);
  border-radius: 6px;
  background: var(--bg-soft);
  overflow: hidden;
}
.inline-diff__head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 9px;
  border-bottom: 1px solid var(--border-soft);
  font-size: 11px;
}
.inline-diff__file {
  font-family: var(--mono);
  color: var(--fg-dim);
  max-width: 60%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.inline-diff__stats {
  display: inline-flex;
  gap: 6px;
  font-family: var(--mono);
  font-size: 10.5px;
}
.inline-diff__add {
  color: var(--add-fg);
}
.inline-diff__del {
  color: var(--del-fg);
}
.inline-diff__spacer {
  flex: 1;
}
.inline-diff__btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 6px;
  font-family: var(--sans);
  font-size: 10.5px;
  color: var(--fg-dim);
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 4px;
  cursor: pointer;
}
.inline-diff__btn:hover {
  color: var(--fg);
  background: var(--bg-elev);
}
.inline-diff__body {
  margin: 0;
  padding: 4px 0;
  font-family: var(--mono);
  font-size: 11.5px;
  line-height: 1.55;
  max-height: 320px;
  overflow: auto;
  background: var(--code-bg, var(--bg-soft));
  color: var(--code-fg, var(--fg));
}
.inline-diff__table {
  display: block;
  min-width: max-content;
  width: 100%;
}
.inline-diff__row {
  display: flex;
  --inline-diff-row-bg: var(--code-bg, var(--bg-soft));
  background: var(--inline-diff-row-bg);
  box-sizing: border-box;
  min-width: 100%;
  width: 100%;
}
.inline-diff__row--add {
  --inline-diff-row-bg: var(--code-add-bg, var(--code-bg, var(--bg-soft)));
}
.inline-diff__row--del {
  --inline-diff-row-bg: var(--code-del-bg, var(--code-bg, var(--bg-soft)));
}
.inline-diff__gutter {
  position: sticky;
  left: 0;
  z-index: var(--z-local-raised);
  display: grid;
  grid-template-columns: 3ch 3ch 10px;
  gap: 5px;
  flex: 0 0 auto;
  padding: 0 6px 0 8px;
  background: var(--inline-diff-row-bg);
  box-shadow: 1px 0 0 var(--code-border, var(--border-soft));
  user-select: none;
}
.inline-diff__line {
  color: var(--fg-faint);
  font-variant-numeric: tabular-nums;
  text-align: right;
}
.inline-diff__sign {
  width: 10px;
  flex-shrink: 0;
  text-align: center;
  opacity: 0.6;
  user-select: none;
}
.inline-diff__text {
  flex: 1 0 auto;
  padding: 0 8px 0 6px;
  white-space: pre-wrap;
  word-break: break-word;
}
.inline-diff__more {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  width: 100%;
  padding: 5px 0;
  font-size: 11px;
  color: var(--fg-dim);
  background: transparent;
  border: 0;
  border-top: 1px solid var(--border-soft);
  cursor: pointer;
}
.inline-diff__more:hover {
  color: var(--accent);
  background: var(--bg-elev);

}

/* --- Right panel tabs (Files / Context) ------------------------------- */
.right-panel {
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
}
.right-panel__tabs {
  display: flex;
  gap: 2px;
  padding: 4px 8px 0;
  border-bottom: 1px solid var(--border);
  flex-shrink: 0;
}
.right-panel__tab {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  font-size: 11px;
  color: var(--fg-faint);
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  transition: color 0.12s, border-color 0.12s;
}
.right-panel__tab:hover { color: var(--fg); }
.right-panel__tab--active {
  color: var(--fg);
  border-bottom-color: var(--accent);
}

.sidebar {
  padding-top: 12px;
}

.sidebar__new {
  display: none;
}

.sidebar__section--projects {
  flex: 1 1 auto;
  min-height: 160px;
}

.app-chrome {
  grid-row: 1;
  grid-column: 1 / -1;
  position: relative;
  z-index: var(--z-app-chrome);
  display: flex;
  align-items: center;
  min-width: 0;
  height: var(--app-chrome-height);
  padding: 0;
  background: var(--bg-soft);
  border-bottom: 1px solid var(--border-soft);
  --wails-draggable: drag;
  user-select: none;
}

.app-chrome button {
  --wails-draggable: no-drag;
}

.app-chrome__panel-toggle {
  position: absolute;
  top: 0;
  flex: 0 0 var(--chrome-toggle-size);
  width: var(--chrome-toggle-size);
  height: var(--app-chrome-height);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--fg-faint);
  opacity: 0.86;
  transition: color 0.12s, background 0.12s, opacity 0.12s;
}

.app-chrome__panel-toggle--left {
  left: var(--chrome-left-toggle-offset);
  border-left: 1px solid var(--border-soft);
  border-right: 1px solid var(--border-soft);
}

.app-chrome__panel-toggle--right {
  right: var(--chrome-right-toggle-offset);
  border-left: 1px solid var(--border-soft);
  border-right: 1px solid var(--border-soft);
}

.layout--resizing .app-chrome__panel-toggle {
  pointer-events: none;
  opacity: 0.65;
}

.app-chrome__panel-toggle:hover {
  color: var(--fg);
  background: color-mix(in srgb, var(--fg-faint) 10%, transparent);
  opacity: 1;
}

.app-chrome__panel-toggle--active {
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 7%, transparent);
  opacity: 1;
}

.app-chrome__panel-toggle--active:hover {
  color: var(--accent-strong);
  background: color-mix(in srgb, var(--fg-faint) 10%, transparent);
}

.app-chrome__panel-toggle--blocked,
.app-chrome__panel-toggle--blocked:hover {
  color: var(--fg-faint);
  background: transparent;
  cursor: not-allowed;
  opacity: 0.55;
}

.app-chrome__spacer {
  flex: 1 1 auto;
  min-width: 16px;
}

.app-chrome__tab-strip {
  flex: 1 1 auto;
  min-width: 0;
  max-width: 100%;
  height: 100%;
  display: flex;
  align-items: stretch;
  overflow: hidden;
}

.app-chrome__identity {
  flex: 0 0 auto;
  min-width: 128px;
  max-width: 220px;
  height: 100%;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--fg-dim);
  overflow: hidden;
  --wails-draggable: drag;
}

.app-chrome__logo {
  flex: 0 0 auto;
  width: 78px;
  max-height: 20px;
  object-fit: contain;
}

.app-chrome__separator {
  flex: 0 0 auto;
  color: var(--fg-faint);
  opacity: 0.72;
}

.app-chrome__scope {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12.5px;
  font-weight: 560;
}

.app-chrome__tools {
  flex: 0 0 auto;
  height: 100%;
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  min-width: 0;
  margin-left: 8px;
  --wails-draggable: no-drag;
  transition:
    margin 0.28s cubic-bezier(0.2, 0.72, 0.2, 1),
    transform 0.18s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.app-chrome__command {
  margin-left: 0;
}

.app-chrome__tools--fixed {
  position: absolute;
  top: 0;
  right: calc(var(--chrome-toggle-size) + 8px);
  z-index: var(--z-local-raised);
  margin-left: 0;
}

.windows-window-controls {
  position: fixed;
  top: 0;
  right: 0;
  z-index: var(--z-dock);
  width: var(--windows-window-controls-width, 138px);
  height: var(--windows-window-controls-height, 48px);
  display: flex;
  align-items: stretch;
  justify-content: flex-end;
  color: var(--fg-dim);
  background: var(--bg-elev);
  border-left: 1px solid var(--border-soft);
  border-bottom: 1px solid var(--border-soft);
  box-shadow: -12px 0 18px -18px color-mix(in srgb, var(--fg) 46%, transparent);
  pointer-events: auto;
  user-select: none;
  --wails-draggable: no-drag;
  transition: opacity var(--dur-base) ease;
}

/* Full-window image previews own their close affordance. Management pages
   reserve caption space and retain native window controls. */
.app--windows-frameless:has(.image-viewer-backdrop) > .windows-window-controls {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

/* When the workspace panel is closed (no layout--workspace-open or
/* When the workspace panel is closed (no layout--workspace-open or
   layout--workspace-maximized), make the window controls box transparent so it
   blends into the title bar / background instead of showing a distinct box. */
.app--windows-frameless .layout:not(.layout--workspace-open):not(.layout--workspace-maximized) ~ .windows-window-controls {
  background: transparent;
  border: none;
  box-shadow: none;
}
:root[data-theme-style] .app--windows-frameless .layout:not(.layout--workspace-open):not(.layout--workspace-maximized) ~ .windows-window-controls {
  background: transparent;
  border: none;
  box-shadow: none;
}

/* When a drawer/palette overlay is open, dim the window controls so they
/* When a drawer/palette overlay is open, dim the window controls so they
   visually sit behind the backdrop instead of staying highlighted on top. */
.drawer-backdrop[data-state="open"] ~ .windows-window-controls {
  opacity: 0.35;
}
:root[data-theme-style] .drawer-backdrop[data-state="open"] ~ .windows-window-controls {
  opacity: 0.35;
}

.windows-window-control {
  flex: 0 0 var(--windows-window-control-width, 46px);
  width: var(--windows-window-control-width, 46px);
  min-width: var(--windows-window-control-width, 46px);
  height: 100%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: inherit;
  transition:
    background var(--dur-fast),
    color var(--dur-fast);
  --wails-draggable: no-drag;
