  border-radius: 8px;
  background: var(--bg-elev);
  color: var(--fg-dim);
  font: inherit;
  font-size: 12.5px;
  line-height: 1;
  transition: color 0.12s, border-color 0.12s, background 0.12s;
}

.topicbar__action-btn--label {
