.tabbar {
  --tabbar-tab-width: 176px;
  flex: 1 1 auto;
  min-width: 0;
  height: 38px;
  display: flex;
  align-items: center;
  padding: 0 10px 0 0;
  gap: 3px;
  background: transparent;
  border-bottom: none;
  overflow: hidden;
}

.tabbar__tabs {
  display: flex;
  align-self: stretch;
  flex: 0 1 auto;
  max-width: calc(100% - 36px);
  gap: 0;
  overflow-x: auto;
  scrollbar-width: none;
}

.tabbar__tabs::-webkit-scrollbar {
  display: none;
}

.tabbar__tab {
  flex: 0 0 var(--tabbar-tab-width);
  position: relative;
  width: var(--tabbar-tab-width);
  height: 38px;
  min-width: var(--tabbar-tab-width);
  max-width: var(--tabbar-tab-width);
  display: flex;
  align-items: center;
  padding: 0 28px 0 10px;
  gap: 6px;
  border: none;
  border-right: 1px solid var(--border-soft);
  border-radius: 0;
  color: var(--fg-dim);
  background: transparent;
  font-size: 12.5px;
  white-space: nowrap;
  transition: background var(--dur-fast) var(--ease-out);
  animation: tab-in var(--dur-base) var(--ease-out) both;
}
@keyframes tab-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
}

.tabbar__tab:not(.tabbar__tab--active):hover {
  background: color-mix(in srgb, var(--bg-elev-2) 42%, transparent);
}

.tabbar__tab--active {
  color: var(--fg);
