  border: 1px solid var(--border);
  border-radius: 12px;
  background: color-mix(in srgb, var(--bg-elev) 72%, var(--bg-soft));
  color: var(--fg-faint);
}

.project-tree__search input {
  flex: 1;
  min-width: 0;
  border: none;
  outline: none;
  background: transparent;
  color: var(--fg);
  font: inherit;
  font-size: 13px;
}

.project-tree__search input::placeholder {
  color: var(--fg-faint);
}

.project-tree__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  min-height: 28px;
  padding: 2px var(--project-tree-edge-gap) 0 8px;
  color: var(--fg-dim);
  font-size: 13px;
  font-weight: 650;
  text-transform: none;
  letter-spacing: 0;
}

.project-tree__header-title {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  flex: 1 1 auto;
}

.project-tree__header-icon {
  flex: 0 0 auto;
}

.project-tree__header-actions {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 3px;
  min-width: 0;
}

.project-tree__action-slot {
  flex: 0 0 var(--project-tree-action-column);
  width: var(--project-tree-action-column);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.project-tree__header-action-slot {
  flex-basis: 22px;
  width: 22px;
  height: 22px;
}

.project-tree__add-project,
.project-tree__collapse-all,
.project-tree__header-action-btn,
.project-tree__new-topic {
  --wails-draggable: no-drag;
  width: 24px;
  height: 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border-soft);
  border-radius: 7px;
  background: transparent;
  color: var(--fg-faint);
  padding: 0;
  opacity: 0.78;
}

.project-tree__header-actions .project-tree__add-project,
.project-tree__header-actions .project-tree__collapse-all,
.project-tree__header-actions .project-tree__header-action-btn {
  width: 22px;
  height: 22px;
  border-radius: 7px;
  background: var(--bg-elev);
  box-shadow: 0 1px 2px color-mix(in srgb, var(--shadow-color) 9%, transparent);
}

.project-tree__add-project:hover:not(:disabled),
.project-tree__collapse-all:hover:not(:disabled),
.project-tree__header-action-btn:hover {
  background: var(--button-bg);
  border-color: color-mix(in srgb, var(--accent) 28%, var(--border-soft));
  color: var(--fg);
  opacity: 1;
}

.project-tree__add-project:disabled,
.project-tree__collapse-all:disabled,
.project-tree__header-action-btn:disabled {
  cursor: default;
  opacity: 0.34;
}

.project-tree__collapse-all--restore:not(:disabled) {
  border-color: color-mix(in srgb, var(--accent) 24%, var(--border-soft));
  background: color-mix(in srgb, var(--accent) 9%, var(--bg-elev));
  color: var(--accent);
  opacity: 0.96;
}

/* Header-action-btn in the header-actions row uses min-width so it can
/* Header-action-btn in the header-actions row uses min-width so it can
   expand when a time-filter label is shown alongside the clock icon. */
.project-tree__header-actions .project-tree__header-action-btn {
  width: auto;
  min-width: 22px;
  padding: 0 4px;
}

/* Time-filter action slot: no fixed width so the button can grow when label shown. */
.project-tree__header-action-slot--filter {
  flex-basis: auto !important;
  width: auto !important;
}

.project-tree__header-action-btn--active {
  border-color: color-mix(in srgb, var(--accent) 24%, var(--border-soft));
  background: color-mix(in srgb, var(--accent) 9%, var(--bg-elev));
  color: var(--accent);
  opacity: 0.96;
}

.project-tree__time-filter {
  display: inline-flex;
  position: relative;
}

.project-tree__time-filter-label {
  font-size: 9px;
  line-height: 1;
  margin-left: 3px;
  font-weight: 500;
}

.project-tree__time-filter-menu {
  position: absolute;
  top: calc(100% + 4px);
  /* Right-aligned: the trigger sits in the right-aligned header inside the
     overflow:hidden sidebar, so opening leftward keeps the menu unclipped. */
  right: 0;
  z-index: var(--z-menu);
  min-width: 84px;
  padding: 4px;
  border: none;
  border-radius: 8px;
  background: var(--bg-elev);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.18);
}

.project-tree__time-filter-opt {
  --wails-draggable: no-drag;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  width: 100%;
  height: 28px;
  padding: 0 8px;
  border: none;
  border-radius: 5px;
  background: transparent;
  color: var(--fg-faint);
  font-size: 12px;
  white-space: nowrap;
  cursor: pointer;
  transition: background 0.12s, color 0.12s;
}

.project-tree__time-filter-opt:hover {
  background: var(--sidebar-hover);
  color: var(--fg);
}

.project-tree__time-filter-opt--on {
  color: var(--accent);
  font-weight: 400;
}

.project-tree__time-filter-sep {
  height: 1px;
  margin: 4px 8px;
  background: var(--border-soft);
}

.project-tree__time-filter-title {
  padding: 4px 8px 2px;
  color: var(--fg-faint);
  font-size: 10px;
  white-space: nowrap;
  user-select: none;
}

/* Classic hover preview card: rendered through a body portal so the sidebar's
/* Classic hover preview card: rendered through a body portal so the sidebar's
   overflow clipping cannot cut it off; pointer-events stay off so it never
   steals the hover from the row underneath. */
.project-tree__hover-card {
  position: fixed;
  z-index: var(--z-menu);
  min-width: 180px;
  max-width: 260px;
  padding: 10px 12px;
  border-radius: 10px;
  background: var(--bg-elev);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.22);
  pointer-events: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.project-tree__hover-card-title {
  color: var(--fg);
  font-size: 12px;
  font-weight: 550;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.project-tree__hover-card-status {
  color: var(--accent);
  font-size: 11px;
}

.project-tree__hover-card-meta {
  color: var(--fg-faint);
  font-size: 11px;
}

.project-tree__hover-card-project {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--fg-faint);
  font-size: 11px;
}

.project-tree__hover-card-project svg {
  color: var(--fg-faint);
  flex: 0 0 auto;
}

/* Classic per-folder show-more toggle and empty-folder placeholder rows. */
.project-tree__topic-window-toggle {
  --wails-draggable: no-drag;
  display: flex;
  align-items: center;
  width: 100%;
  height: 24px;
  padding: 0 8px;
  border: none;
  border-radius: 5px;
  background: transparent;
  color: var(--fg-faint);
  font-size: 11px;
  white-space: nowrap;
  cursor: pointer;
  transition: color 0.12s;
}

.project-tree__topic-window-toggle:hover {
  color: var(--fg-faint);
}

.project-tree__topic-window-toggle:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.project-tree__topic-placeholder {
  display: flex;
  align-items: center;
  height: 26px;
  padding: 0 8px;
  color: var(--fg-faint);
  font-size: 12px;
  user-select: none;
}

.project-tree__skeleton {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-top: 6px;
  padding-bottom: 6px;
}

.project-tree__skeleton-bar {
  display: block;
  height: 12px;
  width: 72%;
  border-radius: 4px;
  background: var(--fg-faint);
  opacity: 0.16;
  animation: pulse 1.2s ease-in-out infinite;
}

.project-tree__skeleton-bar--short {
  width: 48%;
}

.project-tree__header-actions .project-tree__add-project:focus-visible,
.project-tree__header-actions .project-tree__collapse-all:focus-visible,
.project-tree__header-actions .project-tree__header-action-btn:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.project-tree__list {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 0 var(--project-tree-edge-gap) 0 8px;
  scrollbar-width: none;
}

.project-tree__list::-webkit-scrollbar {
  display: none;
}

.app--classic .project-tree__section {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.app--classic .project-tree__section--pinned {
  margin-bottom: 12px;
}

.app--classic .project-tree__section-title {
  min-height: 26px;
  padding: 6px 8px 2px;
  color: var(--fg-faint);
  font-size: 11px;
  font-weight: 600;
  line-height: 1.35;
  letter-spacing: 0;
}

.project-tree__folder {
  position: relative;
  height: 34px;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 0;
  margin-right: 0;
  border-radius: var(--project-tree-row-radius);
  color: var(--fg-dim);
  font-size: 13.5px;
}

.project-tree__folder:hover {
  background: var(--sidebar-hover);
}

.project-tree__folder--active,
.project-tree__folder--menu-open {
  background: color-mix(in srgb, var(--project-accent, var(--accent)) 5%, transparent);
  color: var(--fg);
}

.project-tree__folder--menu-open,
.project-tree__folder--active:hover {
  background: color-mix(in srgb, var(--project-accent, var(--accent)) 5%, var(--sidebar-hover));
}

.project-tree__folder--dragging {
  cursor: grabbing;
  opacity: 0.55;
}

.project-tree__folder--drop-before::before,
.project-tree__folder--drop-after::after {
  content: "";
  position: absolute;
  left: 8px;
  right: 8px;
  height: 2px;
  border-radius: 999px;
  background: var(--accent);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent) 16%, transparent);
  pointer-events: none;
}

.project-tree__folder--drop-before::before {
  top: -2px;
}

.project-tree__folder--drop-after::after {
  bottom: -2px;
}

.project-tree__folder--editing {
  padding-right: 8px;
}

.project-tree__folder-main {
  flex: 1 1 auto;
  min-width: 0;
  height: 100%;
  display: flex;
  align-items: center;
  gap: 7px;
  border: 0;
  border-radius: inherit;
  background: transparent;
  color: inherit;
  font: inherit;
  padding-right: 0;
  text-align: left;
  font-weight: 560;
}

.project-tree__folder--global,
.project-tree__topic--global {
  --project-accent: var(--project-tree-global-accent);
}

.project-tree__folder-color {
  flex: 0 0 auto;
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--project-accent, var(--accent));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--project-accent, var(--accent)) 14%, transparent);
}

.project-tree__folder-main:focus-visible {
  outline: 2px solid var(--accent-soft);
  outline-offset: -2px;
}

.project-tree__folder--draggable {
  cursor: grab;
}

.project-tree__folder--draggable .project-tree__folder-main {
  cursor: inherit;
}

.project-tree__folder--draggable:active {
  cursor: grabbing;
}

.project-tree__folder-toggle {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border: none;
  background: transparent;
  color: inherit;
  padding: 0;
}

.project-tree__folder-label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.project-tree__folder-input {
  --wails-draggable: no-drag;
  flex: 1 1 auto;
  min-width: 0;
  height: 26px;
  border: 1px solid var(--accent-soft);
  border-radius: 7px;
  background: var(--bg-elev);
  color: var(--fg);
  font: inherit;
  font-size: 13px;
  padding: 0 8px;
  outline: none;
}

.project-tree__new-topic {
  opacity: 0.62;
}

.project-tree__new-topic:hover {
  background: var(--button-bg);
  border-color: color-mix(in srgb, var(--accent) 28%, var(--border-soft));
  color: var(--fg);
}

.project-tree__new-topic--active {
  opacity: 1;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  border-color: color-mix(in srgb, var(--accent) 24%, var(--border-soft));
}

.project-tree__topic {
  position: relative;
  width: auto;
  min-height: 34px;
  display: flex;
  align-items: center;
  gap: 4px;
  padding-top: 0;
  padding-bottom: 0;
  padding-left: 0 !important;
  margin-left: 22px;
  margin-right: var(--project-tree-action-column);
  padding-right: 8px;
  border-radius: var(--project-tree-row-radius);
  color: var(--fg-dim);
  font-size: 13px;
  cursor: default;
}

.project-tree__topic--has-meta {
  min-height: 48px;
}

.project-tree__topic--active {
  background: color-mix(in srgb, var(--project-accent, var(--accent)) 10%, var(--sidebar-hover));
  border-radius: 0;
  color: var(--fg);
}

.project-tree__topic--active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  background: color-mix(in srgb, var(--project-accent, var(--accent)) 88%, #ff9d22);
  pointer-events: none;
}

.project-tree__topic--menu-open {
  background: color-mix(in srgb, var(--accent) 6%, var(--sidebar-hover));
  color: var(--fg);
}

.project-tree__topic:hover {
  background: var(--list-row-hover-bg);
}

.project-tree__topic--remote-static:hover {
  background: transparent;
}

.project-tree__topic--active:hover {
  background: color-mix(in srgb, var(--project-accent, var(--accent)) 10%, var(--sidebar-hover));
}

.project-tree__topic-main {
  --wails-draggable: no-drag;
  flex: 1 1 auto;
  min-width: 0;
  min-height: 34px;
  display: flex;
  align-items: center;
  gap: 0;
  border: none;
  border-radius: inherit;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
}

.project-tree__topic--has-meta .project-tree__topic-main {
  min-height: 48px;
  padding-top: 7px;
  padding-bottom: 7px;
}

.project-tree__topic-copy {
  min-width: 0;
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  align-items: flex-start;
  justify-content: center;
  gap: 2px;
  line-height: 1.25;
}

.project-tree__topic-heading {
  width: 100%;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 6px;
}

.project-tree__topic-label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.project-tree__topic-recovery {
  flex: none;
  max-width: 72px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--accent);
  font-size: 10px;
  line-height: 16px;
  padding: 0 4px;
  border: 1px solid color-mix(in srgb, var(--accent) 30%, transparent);
  border-radius: 4px;
}

.project-tree__catalog-rebuild {
  flex: none;
  border: 0;
  padding: 2px 6px;
  border-radius: 4px;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 10%, transparent);
  font: inherit;
  font-size: 11px;
  cursor: pointer;
}

.project-tree__catalog-rebuild:hover {
  background: color-mix(in srgb, var(--accent) 18%, transparent);
}

.project-tree__topic-im {
  flex: 0 1 auto;
  min-width: 0;
  max-width: 74px;
  height: 17px;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 0 5px;
  border-radius: 5px;
  background: color-mix(in srgb, #3b82f6 10%, transparent);
  color: color-mix(in srgb, #2563eb 78%, var(--fg-dim));
  font-size: 10.5px;
  font-weight: 650;
  line-height: 1;
  white-space: nowrap;
}

.project-tree__topic-im svg {
  flex: 0 0 auto;
}

.project-tree__topic-im span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.project-tree__topic-im--weixin {
  background: color-mix(in srgb, #22c55e 11%, transparent);
  color: color-mix(in srgb, #16a34a 78%, var(--fg-dim));
}

.project-tree__topic-im--feishu,
.project-tree__topic-im--lark {
  background: color-mix(in srgb, #0ea5e9 11%, transparent);
  color: color-mix(in srgb, #0284c7 78%, var(--fg-dim));
}

.project-tree__topic-status {
  flex: 0 0 auto;
  max-width: 64px;
  height: 17px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 5px;
  border-radius: 5px;
  background: color-mix(in srgb, var(--project-accent, var(--accent)) 11%, transparent);
  color: color-mix(in srgb, var(--project-accent, var(--accent)) 72%, var(--fg-dim));
  font-size: 10.5px;
  font-weight: 620;
  line-height: 1;
  white-space: nowrap;
}

.project-tree__topic-status--waiting_confirmation {
  background: color-mix(in srgb, var(--warn) 13%, transparent);
  color: color-mix(in srgb, var(--warn) 82%, var(--fg));
}

.project-tree__topic-status--background_job {
  background: color-mix(in srgb, var(--shell-accent) 11%, transparent);
  color: color-mix(in srgb, var(--shell-accent) 78%, var(--fg));
}

.project-tree__topic-status--paused {
  background: color-mix(in srgb, var(--fg-faint) 11%, transparent);
  color: var(--fg-faint);
}

.project-tree__topic-status--awaiting_delivery {
  max-width: 80px;
  background: color-mix(in srgb, var(--warn) 13%, transparent);
  color: color-mix(in srgb, var(--warn) 82%, var(--fg));
}

.project-tree__topic-status--error {
  background: color-mix(in srgb, var(--err) 12%, transparent);
  color: color-mix(in srgb, var(--err) 84%, var(--fg));
}

.project-tree__topic-meta {
  max-width: 100%;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 5px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--fg-faint);
  font-size: 11px;
  line-height: 1.2;
}

.project-tree__topic--session .project-tree__topic-label {
  color: var(--fg-dim);
}

.project-tree__topic-main:focus-visible {
  outline: 2px solid var(--accent-soft);
  outline-offset: -2px;
}

/* Classic single-line rows: the activity time sits right-aligned on the title
/* Classic single-line rows: the activity time sits right-aligned on the title
   line (turns and the exact date live in the hover preview card). Mirrors the
   workbench side recipe, including the swap with the shortcut badge. */
.app--classic .project-tree__topic-side {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 5px;
  margin-left: 6px;
  color: var(--fg-faint);
  font-size: 11px;
  line-height: 1;
  white-space: nowrap;
  transition: opacity var(--dur-fast);
}

.app--classic .project-tree__topic-side--empty {
  visibility: hidden;
}

.app--classic .project-tree__topic-time {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.app--classic .project-tree__topic-state {
  width: 10px;
  height: 10px;
  border-radius: 999px;
  background: currentColor;
  opacity: 0.78;
}

.app--classic .project-tree__topic-state--thinking,
.app--classic .project-tree__topic-state--streaming {
  border: 2px solid color-mix(in srgb, currentColor 26%, transparent);
  border-top-color: currentColor;
  background: transparent;
  animation: project-tree-spin 0.9s linear infinite;
}

.app--classic .project-tree__topic-state--waiting_confirmation {
  background: var(--warn);
  animation: none;
}

.app--classic .project-tree__topic-state--paused {
  background: var(--fg-faint);
}

.app--classic .project-tree__topic-state--error {
  background: var(--err);
}

.app--classic .project-tree__topic--show-shortcut .project-tree__topic-side {
  opacity: 0;
}

@media (prefers-reduced-motion: reduce) {
  .app--classic .project-tree__topic-state--thinking,
  .app--classic .project-tree__topic-state--streaming {
    animation: none;
  }
}

.project-tree__topic--editing {
  padding-right: 8px;
}

.project-tree__topic-input {
  --wails-draggable: no-drag;
  flex: 1 1 auto;
  min-width: 0;
  align-self: stretch;
  border: 1px solid var(--accent-soft);
  border-radius: 7px;
  background: var(--bg-elev);
  color: var(--fg);
  font: inherit;
  font-size: 13px;
  padding: 0 8px;
  outline: none;
}

.project-tree__children {
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  transform: translateY(-4px);
  pointer-events: none;
  transition: opacity 0.16s ease, transform 0.2s cubic-bezier(0.22, 1, 0.36, 1);
}

.project-tree__children--expanded {
  grid-template-rows: 1fr;
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
}

.project-tree__children-inner {
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}

/* Project tree: icon stack holds folder open/closed icon */
.project-tree__icon-stack {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
  position: relative;
}
.project-tree__icon-stack > .project-tree__folder-icon {
  width: 14px;
