:root:not([data-theme-style]) {
  --bg: #090b0e;
  --bg-soft: #101318;
  --bg-elev: #141820;
  --bg-elev-2: #1b202a;
  --sidebar-bg: #0d1015;
  --sidebar-hover: #181d26;
  --sidebar-active: color-mix(in srgb, var(--accent) 10%, var(--bg-elev));
  --chat-bg: #0b0d11;
  --workspace-preview-bg: #0b0d11;
  --workspace-files-bg: color-mix(in srgb, var(--bg-elev) 66%, var(--chat-bg));
  --workspace-files-hover: color-mix(in srgb, var(--fg-faint) 10%, transparent);
  --border: #29313c;
  --border-soft: #1d232c;
  --fg: #f5f6f8;
  --fg-dim: #b8bec8;
  --fg-faint: #7f8794;
  --accent: #d97757;
  --accent-fg: #170b06;
  --accent-soft: rgba(217, 119, 87, 0.14);
  --accent-strong: #e38b6b;
  --ok: #76c878;
  --warn: #d9a441;
  --button-radius: 7px;
