}

:root[data-theme="light"]:not([data-theme-style]) {
  --bg: #e9edf3;
  --bg-soft: #f0f3f8;
  --bg-elev: #ffffff;
  --bg-elev-2: #eef2f7;
  --sidebar-bg: #f9f9f9;
  --sidebar-hover: #e7edf5;
  --sidebar-active: color-mix(in srgb, var(--accent) 9%, #ffffff);
  --chat-bg: #f8fafc;
  --workspace-preview-bg: #f8fafc;
  --workspace-files-bg: #f1f4f8;
  --workspace-files-hover: #e8edf5;
  --border: #d5dde8;
  --border-soft: #e3e9f1;
  --fg: #121722;
  --fg-dim: #4d5666;
  --fg-faint: #8791a1;
}

@media (prefers-color-scheme: light) {
  :root:not([data-theme]):not([data-theme-style]) {
    --bg: #e9edf3;
    --bg-soft: #f0f3f8;
    --bg-elev: #ffffff;
    --bg-elev-2: #eef2f7;
    --sidebar-bg: #f9f9f9;
    --sidebar-hover: #e7edf5;
    --sidebar-active: color-mix(in srgb, var(--accent) 9%, #ffffff);
    --chat-bg: #f8fafc;
    --workspace-preview-bg: #f8fafc;
    --workspace-files-bg: #f1f4f8;
    --workspace-files-hover: #e8edf5;
    --border: #d5dde8;
    --border-soft: #e3e9f1;
    --fg: #121722;
    --fg-dim: #4d5666;
    --fg-faint: #8791a1;
