.layout {
  --chat-min-width: 400px;
  --topicbar-height: 58px;
  --statusbar-height: var(--statusbar-dock-height);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--bg) 94%, var(--accent) 6%), var(--bg) 360px);
}

.app-chrome {
  background: color-mix(in srgb, var(--bg-soft) 90%, var(--bg-elev));
  border-bottom-color: var(--border-soft);
}

.app--darwin .app-chrome--tabs {
