/* -------------------------------------------------------------------------
/* -------------------------------------------------------------------------
   Shared desktop implementation
   Keeps every theme on the Graphite-tuned app shell. Theme styles should swap
   color tokens, not spacing, positioning, density, or component geometry.
   ------------------------------------------------------------------------- */
:root[data-theme-style] {
  --chrome-panel-control-size: 30px;
  --app-graphite-hairline: rgba(20, 22, 28, 0.12);
  --app-graphite-hairline-strong: rgba(20, 22, 28, 0.22);
  --app-graphite-shadow: 0 1px 2px rgba(20, 22, 28, 0.06);
  --app-graphite-shadow-float: 0 12px 34px rgba(20, 22, 28, 0.14);
  --button-radius: 7px;
  --list-row-radius: 8px;
  --tree-row-radius: 7px;
  --r-s: 5px;
  --r: 8px;
  --r-l: 11px;
  --radius: 8px;
  --dur-fast: 130ms;
  --dur-base: 220ms;
  --dur-slow: 320ms;
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
}

:root[data-theme="dark"][data-theme-style] {
  --app-graphite-hairline: rgba(255, 255, 255, 0.1);
  --app-graphite-hairline-strong: rgba(255, 255, 255, 0.2);
  --app-graphite-shadow: 0 1px 2px rgba(0, 0, 0, 0.5);
  --app-graphite-shadow-float: 0 14px 40px rgba(0, 0, 0, 0.6);
}

:root[data-theme-style] body {
  background: var(--bg);
}

:root[data-theme-style] .layout {
  --app-chrome-height: 46px;
  --topicbar-height: 58px;
  background: var(--bg);
}

:root[data-theme-style] .layout--workbench-chrome-hidden {
  --app-chrome-height: 0px;
  grid-template-rows: minmax(0, 1fr) var(--statusbar-height);
  background: var(--bg);
}

:root[data-theme-style] .app--darwin .layout {
  --app-chrome-height: 46px;
}

:root[data-theme-style] .app--darwin .layout--workbench-chrome-hidden {
  --app-chrome-height: 0px;
}

:root[data-theme-style] .app-chrome,
:root[data-theme-style] .workspace-tabs-bar {
  background: var(--bg-elev);
  border-bottom: 1px solid var(--border-soft);
  box-shadow: none;
}

:root[data-theme-style] .app--darwin .app-chrome--tabs {
  padding-left: calc(var(--chrome-left-safe-offset) + var(--chrome-toggle-size) + 8px);
  padding-right: calc(var(--chrome-toggle-size) + var(--chrome-toggle-size) + 16px);
  background: var(--bg-elev);
  transition: background var(--dur-fast), border-color var(--dur-fast);
}

:root[data-theme-style] .app--windows .app-chrome--native-tabs,
:root[data-theme-style] .app--linux .app-chrome--native-tabs {
  gap: 12px;
  padding-left: 48px;
  padding-right: calc(var(--chrome-right-toggle-offset) + 48px);
  background: var(--bg-elev);
  transition: background var(--dur-fast), border-color var(--dur-fast);
}

:root[data-theme-style] .app--windows .app-chrome--native-tabs {
  background:
