  gap: 5px;
  margin-top: 6px;
  padding: 6px 0 0;
  border-top: 0;
}

.sidebar--workbench .sidebar__nav--footer .sidebar__navitem,
.sidebar--workbench .sidebar__nav--footer .sidebar-im__summary {
