}

.sidebar--workbench .sidebar__nav--footer .sidebar__navitem:hover,
.sidebar--workbench .sidebar__nav--footer .sidebar-im__summary:hover,
.sidebar--workbench .sidebar__nav--footer .sidebar-im--expanded .sidebar-im__summary {
