  border-radius: 10px;
  background: var(--sidebar-workbench-fill-strong);
}

.sidebar--workbench .sidebar__utility-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
}

.sidebar--workbench .sidebar__utility-row .tooltip-trigger {
  min-width: 0;
}

.sidebar--workbench .sidebar__utility-button {
  width: 100%;
  height: 32px;
  justify-content: center;
  border: 1px solid transparent;
  border-radius: 9px;
