}

.project-tree__group {
  position: relative;
}
.project-tree__group-main {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 5px 6px;
  border-radius: 6px;
  color: var(--color-text-muted, inherit);
  font-size: var(--text-md);
  font-weight: 600;
  letter-spacing: 0;
  cursor: pointer;
  background: transparent;
  border: 1px dashed transparent;
}
.project-tree__group-main:hover {
  background: color-mix(in srgb, currentColor 8%, transparent);
}
.project-tree__group-main--drop-target {
  border-color: color-mix(in srgb, currentColor 18%, transparent);
}
.project-tree__group-chevron {
  flex: 0 0 auto;
  width: 10px;
  font-size: 9px;
  opacity: 0.7;
}
.project-tree__group-title {
  flex: 1 1 auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: left;
}
.project-tree__group-count {
  flex: 0 0 auto;
  font-size: 10px;
  opacity: 0.6;
  font-weight: 400;
}
.project-tree__group-input {
  flex: 1 1 auto;
  min-width: 0;
  font-size: inherit;
  font-weight: 600;
  padding: 1px 4px;
  border-radius: 4px;
  border: 1px solid color-mix(in srgb, currentColor 35%, transparent);
