  color: inherit;
  outline: none;
}
.project-tree__group-children {
  padding-left: 0;
}
.project-tree__folder-active-indicator {
  width: 10px;
  height: 10px;
  flex: 0 0 10px;
  margin-left: 6px;
  border: 2px solid color-mix(in srgb, currentColor 26%, transparent);
  border-top-color: currentColor;
  border-radius: 999px;
  animation: project-tree-spin 0.9s linear infinite;
  pointer-events: none;
}
@media (prefers-reduced-motion: reduce) {
  .project-tree__folder-active-indicator {
    animation: none;
    border-color: currentColor;
    opacity: 0.72;
  }
}
.project-tree__topic--drop-before {
  box-shadow: inset 0 2px 0 currentColor;
}
.project-tree__topic--drop-after {
  box-shadow: inset 0 -2px 0 currentColor;
}

@keyframes project-tree-spin {
  to {
    transform: rotate(360deg);
  }
}

.project-tree__topic-action--busy svg,
.project-tree__archive-spinner {
  animation: project-tree-spin 0.9s linear infinite;
}

@media (prefers-reduced-motion: reduce) {
  .sidebar--workbench .project-tree__topic-state--thinking,
  .sidebar--workbench .project-tree__topic-state--streaming,
  .project-tree__topic-action--busy svg,
  .project-tree__archive-spinner {
    animation: none;
  }
}

@media (max-height: 760px) {
  .sidebar--workbench .sidebar__quick-actions {
    gap: 6px;
    margin-bottom: 12px;
  }

  .sidebar--workbench .sidebar__quick-action {
    height: 34px;
    gap: 8px;
    padding: 0 9px;
    font-size: 12.5px;
    font-weight: 560;
  }

  .sidebar--workbench .sidebar__quick-action svg {
    width: 16px;
    height: 16px;
  }

  .sidebar--workbench .project-tree__header {
    padding-top: 10px;
  }
}

/* ── Toast ──────────────────────────────────────────────────────────── */
.toast-container {
  position: fixed;
  top: 16px;
  left: 50%;
  transform: translateX(-50%);
  z-index: var(--z-toast);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  pointer-events: none;
}
:root[data-platform="darwin"] .toast-container {
  top: 48px;
}
.toast {
  max-width: min(560px, calc(100vw - 32px));
  pointer-events: auto;
  cursor: pointer;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 10px 20px;
  font-size: 14px;
  color: var(--fg);
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.2);
  white-space: normal;
  display: flex;
  align-items: center;
  gap: 8px;
  animation: toast-in 0.2s ease-out;
  user-select: none;
}
.toast--warn {
  border-color: color-mix(in srgb, var(--warn) 38%, var(--border));
  background: color-mix(in srgb, var(--warn) 12%, var(--bg-elev));
  color: color-mix(in srgb, var(--warn) 78%, var(--fg));
}
.toast--error {
  border-color: color-mix(in srgb, var(--danger) 38%, var(--border));
  background: color-mix(in srgb, var(--danger) 12%, var(--bg-elev));
  color: color-mix(in srgb, var(--danger) 78%, var(--fg));
}
.toast__icon {
  flex: 0 0 auto;
  line-height: 1;
  font-size: 14px;
}
.toast__text {
  min-width: 0;
  line-height: 1.4;
  overflow-wrap: anywhere;
}
.toast__action {
  --wails-draggable: no-drag;
  flex: 0 0 auto;
  height: 26px;
  border: 1px solid color-mix(in srgb, currentColor 30%, transparent);
  border-radius: 7px;
  background: color-mix(in srgb, currentColor 8%, transparent);
  color: inherit;
  padding: 0 9px;
  font: inherit;
  font-size: 12px;
  font-weight: 650;
  line-height: 1;
  cursor: pointer;
}
.toast__action:hover,
.toast__action:focus-visible {
  background: color-mix(in srgb, currentColor 13%, transparent);
  outline: none;
}
@keyframes toast-in {
  from { opacity: 0; transform: translateY(-8px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ==========================================================================
/* ==========================================================================
   Creation desktop style — scaffold
   --------------------------------------------------------------------------
   The "creation" desktop layout style (Settings → Desktop style → Creation).
   It currently reuses the classic JSX structure and is isolated entirely
   within this .app--creation scope, ready to be redesigned.

   RULES (see AGENTS.md):
   - Only style under the .app--creation scope here.
   - Do NOT touch global base tokens (--bg / --border / --text-base /
     --scrollbar-size) — override them scoped to .app--creation if needed.
   ========================================================================== */
.app--creation .layout--creation-chrome-hidden {
  --app-chrome-height: 0px;
  --statusbar-height: 0px;
  grid-template-rows: minmax(0, 1fr);
}

.app--creation .statusbar {
  display: none;
}

.app--creation .settings-modal-backdrop,
:root[data-theme-style] .app--creation .settings-modal-backdrop {
  padding: clamp(24px, 5vh, 48px) clamp(0px, calc(54px - (900px - 100vw) * 0.3857), 54px);
  background: rgba(18, 20, 26, 0.36);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}

.app--creation .settings-modal,
:root[data-theme-style] .app--creation .settings-modal {
  width: min(980px, calc(100vw - clamp(32px, calc(160px - (900px - 100vw) * 0.914), 160px)));
  height: min(690px, calc(100vh - 112px));
  border-color: color-mix(in srgb, var(--fg-faint) 18%, transparent);
  border-radius: 18px;
  background: color-mix(in srgb, var(--bg-elev) 92%, transparent);
  backdrop-filter: blur(18px) saturate(1.08);
  -webkit-backdrop-filter: blur(18px) saturate(1.08);
  box-shadow: 0 24px 72px rgba(0, 0, 0, 0.18), 0 2px 8px rgba(0, 0, 0, 0.06);
