/* Topic shortcut badges (Cmd/Ctrl+1-9 overlay) */

.project-tree__topic-shortcut {
  position: absolute;
  top: 50%;
  right: 8px;
  z-index: var(--z-local-raised);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
  height: 22px;
  padding: 0 6px;
  border-radius: 5px;
  background: color-mix(in srgb, var(--fg) 8%, var(--sidebar-bg, var(--bg)));
  color: var(--fg-faint);
  font-size: 11px;
  font-weight: 520;
  line-height: 1;
  letter-spacing: 0.02em;
  white-space: nowrap;
  pointer-events: none;
  opacity: 0;
  transform: translateY(-50%) translateX(4px);
  transition: opacity 120ms ease, transform 120ms ease;
}

/* Show badges when the parent topic has the modifier held class */
.project-tree__topic--show-shortcut .project-tree__topic-shortcut {
  opacity: 1;
  transform: translateY(-50%) translateX(0);
}

/* In workbench mode, hide the time/side and actions when shortcuts are shown */
.sidebar--workbench .project-tree__topic--show-shortcut .project-tree__topic-side,
.app--classic .project-tree__topic--show-shortcut .project-tree__topic-side {
  opacity: 0;
  transform: translateX(-3px);
}
.sidebar--workbench .project-tree__topic--show-shortcut .project-tree__topic-actions,
.app--classic .project-tree__topic--show-shortcut .project-tree__topic-actions {
  opacity: 0;
  pointer-events: none;
  transform: translateY(-50%) translateX(4px);
}

/* In creation mode, hide the time/side when shortcuts are shown */
.app--creation .project-tree__topic--show-shortcut .project-tree__topic-side {
  opacity: 0;
  transform: translateX(-3px);
}

/* In classic mode, hide the meta line when shortcuts are shown */
.project-tree__topic--show-shortcut .project-tree__topic-meta {
  opacity: 0;
}

/* Theme overrides */
:root[data-theme-style] .project-tree__topic-shortcut {
  background: color-mix(in srgb, var(--fg) 8%, var(--sidebar-bg, var(--bg)));
  color: var(--fg-faint);
}

.app--windows-frameless {
  --windows-window-controls-width: 138px;
  --windows-window-control-width: 46px;
  --windows-window-controls-gap: 18px;
  --windows-window-controls-safe: calc(var(--windows-window-controls-width) + var(--windows-window-controls-gap));
  --windows-window-controls-height: 48px;
}

.app--windows-frameless.app--workbench {
  --windows-window-controls-height: 40px;
}

.app--windows-frameless:not(.app--workbench):not(.app--creation) {
  --windows-window-controls-height: 38px;
}

:root[data-theme-style] .app--windows-frameless:not(.app--workbench):not(.app--creation) {
  --windows-window-controls-height: 46px;
}

.app--windows-frameless.app--creation {
  /* Match Creation topicbar / dock tools (40px) so caption buttons are not taller
     than the title strip. classic/workbench keep their own heights. */
  --windows-window-controls-height: 40px;
  /* Tighter caption buttons free horizontal room for dock tabs at narrow widths.
     classic/workbench keep the standard 46×3 = 138 strip. */
  --windows-window-control-width: 36px;
  --windows-window-controls-width: 108px;
  --windows-window-controls-gap: 8px;
  --windows-window-controls-safe: calc(var(--windows-window-controls-width) + var(--windows-window-controls-gap));
}

.app--windows-frameless .app-chrome--native-tabs,
:root[data-theme-style] .app--windows-frameless .app-chrome--native-tabs {
  --windows-frameless-titlebar-tools-offset: var(--windows-window-controls-safe);
  padding-right: calc(var(--windows-frameless-titlebar-tools-offset) + var(--chrome-panel-control-size, 30px) + 18px);
}

.app--windows-frameless .app-chrome--native-tabs .app-chrome__panel-toggle--right,
:root[data-theme-style] .app--windows-frameless .app-chrome--native-tabs .app-chrome__panel-toggle--right {
  right: calc(var(--windows-frameless-titlebar-tools-offset) + 8px);
}

.app--windows-frameless .topicbar,
:root[data-theme-style] .app--windows-frameless .topicbar {
  padding-right: var(--windows-window-controls-safe);
}

/* When workspace panel is open the workbench-dock covers the right edge, so the
/* When workspace panel is open the workbench-dock covers the right edge, so the
   topicbar no longer needs the window-controls safe space — use the normal 18px
   padding instead to prevent buttons from being pushed off-screen or overlapping
   the dock. */
.app--windows-frameless .layout--workspace-open .topicbar,
.app--windows-frameless .layout--workspace-maximized .topicbar,
:root[data-theme-style] .app--windows-frameless .layout--workspace-open .topicbar,
:root[data-theme-style] .app--windows-frameless .layout--workspace-maximized .topicbar {
  padding-right: 18px;
}

/* Workbench hides AppChrome, so its dock is also the native title surface.
/* Workbench hides AppChrome, so its dock is also the native title surface.
   Keep the Windows caption buttons on a dedicated first row and render the
   complete dock tab strip below it, matching Classic's separated chrome. */
.app--windows-frameless.app--workbench .workbench-dock__tools,
:root[data-theme-style] .app--windows-frameless.app--workbench .workbench-dock__tools {
  position: relative;
  height: calc(40px + var(--windows-window-controls-height));
  padding: var(--windows-window-controls-height) 12px 0;
}

.app--windows-frameless.app--workbench .workbench-dock__tools::before,
:root[data-theme-style] .app--windows-frameless.app--workbench .workbench-dock__tools::before {
  content: "";
  position: absolute;
  top: calc(var(--windows-window-controls-height) - 1px);
  right: 0;
  left: 0;
  height: 1px;
  background: var(--border-soft);
  pointer-events: none;
}

/* macOS keeps dock tabs and the fixed workspace toggle in one title row. The
   toggle stays anchored to the window edge while this row reserves its hit
   area; the four tabs share the remaining width instead of sliding under it. */
.app--darwin.app--workbench .workbench-dock__tools,
:root[data-theme-style] .app--darwin.app--workbench .workbench-dock__tools {
  padding-right: 48px;
}

.app--darwin.app--workbench .workbench-dock__tabs,
:root[data-theme-style] .app--darwin.app--workbench .workbench-dock__tabs {
  flex: 1 1 auto;
  width: 100%;
  min-width: 0;
  gap: 2px;
}

.app--darwin.app--workbench .workbench-dock__tab,
:root[data-theme-style] .app--darwin.app--workbench .workbench-dock__tab {
  flex: 1 1 0;
  min-width: 0;
  max-width: none;
  padding: 0 5px;
  gap: 4px;
  justify-content: center;
}

.app--darwin.app--workbench .workbench-dock__tab-label,
:root[data-theme-style] .app--darwin.app--workbench .workbench-dock__tab-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Workbench keeps its workspace toggle in the fixed top-right dock-toggle
/* Workbench keeps its workspace toggle in the fixed top-right dock-toggle
   instead of an AppChrome rail; shift it left of the Windows caption strip
   (min/max/close) so it never sits under the window controls. Same safe inset
   as the classic-mode panel toggle. */
.app--windows-frameless.app--workbench .app__dock-toggle,
:root[data-theme-style] .app--windows-frameless.app--workbench .app__dock-toggle {
  right: calc(var(--windows-window-controls-safe) + 8px);
}

/* Creation sets tools padding via shorthand; re-assert the Windows safe
/* Creation sets tools padding via shorthand; re-assert the Windows safe
   inset with higher specificity so 「文件 / 改动」 cannot sit under min/max/close.
   Tabs fill this free strip; each tab is an equal column that self-centers. */
.app--windows-frameless.app--creation .workbench-dock__tools,
:root[data-theme-style] .app--windows-frameless.app--creation .workbench-dock__tools {
  padding-left: 8px;
  padding-right: calc(var(--windows-window-controls-width) + 6px);
  justify-content: flex-start;
}

.app--windows-frameless.app--creation .workbench-dock__tabs,
:root[data-theme-style] .app--windows-frameless.app--creation .workbench-dock__tabs {
  width: 100%;
  flex: 1 1 auto;
  max-width: none;
  min-width: 0;
  overflow: hidden;
  justify-content: flex-start;
}

.app--windows-frameless .workbench-dock__tabs,
:root[data-theme-style] .app--windows-frameless .workbench-dock__tabs {
  max-width: calc(100% - 4px);
}

