  color: var(--accent, #4af);
}
.diag-page .frontend-diagnostics--embedded .scroll-diagnostics__status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0 6px;
  white-space: nowrap;
}
.diag-page .frontend-diagnostics--embedded .scroll-diagnostics__dot {
  width: 7px;
  height: 7px;
  flex: 0 0 7px;
  border-radius: 50%;
